'use client'

import { useEffect, useState } from 'react'
import { ArrowLeft, Save, Upload, Loader2 } from 'lucide-react'
import Link from 'next/link'
import { createClient } from '@/utils/supabase/client'
import { useRouter } from 'next/navigation'

export default function EditCenter({ params }: { params: Promise<{ id: string }> }) {
  const router = useRouter()
  const supabase = createClient()
  
  const [centerId, setCenterId] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [uploading, setUploading] = useState(false)
  
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    address: '',
    city: '',
    country: '',
    zipCode: '',
    description: '',
    website: '',
    instagram: '',
    logoUrl: '',
  })

  useEffect(() => {
    const unwrapParams = async () => {
      const { id } = await params
      setCenterId(id)
      fetchCenter(id)
    }
    unwrapParams()
  }, [])

  const fetchCenter = async (id: string) => {
    try {
      const { data, error } = await supabase
        .from('centers')
        .select('*')
        .eq('id', id)
        .single()

      if (error) {
        console.error('Error fetching center:', error)
      } else {
        setFormData({
          name: data.name || '',
          email: data.email || '',
          phone: data.phone || '',
          address: data.address || '',
          city: data.city || '',
          country: data.country || '',
          zipCode: data.zip_code || '',
          description: data.description || '',
          website: data.website || '',
          instagram: data.instagram || '',
          logoUrl: data.logo_url || '',
        })
      }
    } catch (err) {
      console.error('Error:', err)
    } finally {
      setLoading(false)
    }
  }

  const handleInputChange = (e: any) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
  }

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file || !centerId) return

    setUploading(true)
    try {
      const filename = `${centerId}_${Date.now()}_${file.name}`
      const { error } = await supabase.storage
        .from('center-logos')
        .upload(filename, file)

      if (error) {
        alert('Error al subir el archivo')
      } else {
        const { data } = supabase.storage
          .from('center-logos')
          .getPublicUrl(filename)
        setFormData(prev => ({ ...prev, logoUrl: data.publicUrl }))
      }
    } catch (err) {
      console.error('Error uploading file:', err)
    } finally {
      setUploading(false)
    }
  }

  const handleSave = async () => {
    if (!centerId) return
    setSaving(true)

    try {
      const { error } = await supabase
        .from('centers')
        .update({
          name: formData.name,
          email: formData.email,
          phone: formData.phone,
          address: formData.address,
          city: formData.city,
          country: formData.country,
          zip_code: formData.zipCode,
          description: formData.description,
          website: formData.website,
          instagram: formData.instagram,
          logo_url: formData.logoUrl,
        })
        .eq('id', centerId)

      if (error) {
        alert('Error al guardar: ' + error.message)
      } else {
        alert('Cambios guardados exitosamente')
        router.push(`/center/${centerId}`)
      }
    } catch (err) {
      console.error('Error:', err)
      alert('Error al guardar los cambios')
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return <div className="min-h-screen bg-black flex items-center justify-center text-white">Cargando...</div>
  }

  return (
    <div className="min-h-screen bg-black">
      {/* Header */}
      <div className="border-b border-white/10 bg-black px-8 py-6">
        <div className="max-w-4xl mx-auto">
          <Link href={`/center/${centerId}`} className="flex items-center gap-2 text-gray-400 hover:text-white mb-4 transition-colors">
            <ArrowLeft size={18} /> Volver
          </Link>
          <h1 className="text-4xl font-heading font-bold text-white">Editar Centro</h1>
        </div>
      </div>

      {/* Content */}
      <div className="max-w-4xl mx-auto px-8 py-12">
        <div className="space-y-12">
          {/* Logo Section */}
          <div>
            <h2 className="text-2xl font-bold text-white mb-6">Logo del Centro</h2>
            <div className="rounded-xl border-2 border-dashed border-white/20 p-8 text-center hover:border-brand-red/50 transition-all">
              {formData.logoUrl ? (
                <div className="mb-4">
                  <img src={formData.logoUrl} alt="Logo" className="w-24 h-24 mx-auto rounded-lg object-cover" />
                </div>
              ) : (
                <div className="text-5xl mb-4">🏢</div>
              )}
              <p className="text-gray-400 mb-4">Arrastra tu logo aquí o haz clic para cambiar</p>
              <label className="inline-flex items-center gap-2 rounded-lg bg-brand-red/20 hover:bg-brand-red/30 px-4 py-2 text-brand-red font-bold cursor-pointer transition-all">
                <Upload size={18} /> Cambiar Logo
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFileUpload}
                  disabled={uploading}
                  className="hidden"
                />
              </label>
              {uploading && <p className="text-gray-400 mt-2 text-sm">Subiendo...</p>}
            </div>
          </div>

          {/* General Information */}
          <div>
            <h2 className="text-2xl font-bold text-white mb-6">Información General</h2>
            <div className="space-y-6">
              <div>
                <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Nombre del Centro</label>
                <input
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleInputChange}
                  className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                />
              </div>

              <div className="grid gap-6 md:grid-cols-2">
                <div>
                  <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Email</label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Teléfono</label>
                  <input
                    type="tel"
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Descripción</label>
                <textarea
                  name="description"
                  value={formData.description}
                  onChange={handleInputChange}
                  rows={4}
                  className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all resize-none"
                />
              </div>
            </div>
          </div>

          {/* Location */}
          <div>
            <h2 className="text-2xl font-bold text-white mb-6">Ubicación</h2>
            <div className="space-y-6">
              <div>
                <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Dirección</label>
                <input
                  type="text"
                  name="address"
                  value={formData.address}
                  onChange={handleInputChange}
                  className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                />
              </div>

              <div className="grid gap-6 md:grid-cols-3">
                <div>
                  <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Ciudad</label>
                  <input
                    type="text"
                    name="city"
                    value={formData.city}
                    onChange={handleInputChange}
                    className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">País</label>
                  <input
                    type="text"
                    name="country"
                    value={formData.country}
                    onChange={handleInputChange}
                    className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Código Postal</label>
                  <input
                    type="text"
                    name="zipCode"
                    value={formData.zipCode}
                    onChange={handleInputChange}
                    className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                  />
                </div>
              </div>
            </div>
          </div>

          {/* Social Media */}
          <div>
            <h2 className="text-2xl font-bold text-white mb-6">Web y Redes</h2>
            <div className="grid gap-6 md:grid-cols-2">
              <div>
                <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Sitio Web</label>
                <input
                  type="url"
                  name="website"
                  value={formData.website}
                  onChange={handleInputChange}
                  className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Instagram</label>
                <input
                  type="text"
                  name="instagram"
                  value={formData.instagram}
                  onChange={handleInputChange}
                  className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                />
              </div>
            </div>
          </div>

          {/* Save Button */}
          <div className="border-t border-white/10 pt-8 flex gap-4">
            <button
              onClick={handleSave}
              disabled={saving}
              className="flex items-center gap-2 rounded-lg bg-brand-red hover:bg-brand-accent px-6 py-3 text-sm font-bold text-white transition-all shadow-lg hover:shadow-brand-red/20 disabled:opacity-50"
            >
              {saving ? (
                <>
                  <Loader2 size={18} className="animate-spin" />
                  Guardando...
                </>
              ) : (
                <>
                  <Save size={18} /> Guardar Cambios
                </>
              )}
            </button>
            <Link
              href={`/center/${centerId}`}
              className="rounded-lg bg-white/5 hover:bg-white/10 px-6 py-3 text-sm font-bold text-white transition-all"
            >
              Cancelar
            </Link>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { ArrowLeft, Upload, Loader2 } from 'lucide-react'
import Link from 'next/link'
import { createClient } from '@/utils/supabase/client'
import { useRouter } from 'next/navigation'

const centerTypes = [
  { id: 'crossfit', label: 'CrossFit Box', emoji: '🏋️' },
  { id: 'gym', label: 'Gym Convencional', emoji: '💪' },
  { id: 'running', label: 'Club de Running', emoji: '🏃' },
  { id: 'yoga', label: 'Estudio Yoga/Pilates', emoji: '🧘' },
  { id: 'padel', label: 'Pista Pádel/Tenis', emoji: '🎾' },
  { id: 'dance', label: 'Estudio de Danza', emoji: '💃' },
  { id: 'swim', label: 'Piscina/Natación', emoji: '🏊' },
  { id: 'boxing', label: 'Boxeo/MMA', emoji: '🥊' },
  { id: 'other', label: 'Otro', emoji: '🎯' },
]

const plans = [
  { id: 'free', name: 'FREE', price: '€0', description: 'Prueba gratis' },
  { id: 'starter', name: 'STARTER', price: '€49.99', description: '/mes (primeros 3 meses: €29.99)' },
  { id: 'pro', name: 'PRO', price: '€149.99', description: '/mes (primeros 3 meses: €99.99)' },
]

export default function NewOwnerCenter() {
  const router = useRouter()
  const supabase = createClient()
  
  const [user, setUser] = useState<any>(null)
  const [loading, setLoading] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [logoUrl, setLogoUrl] = useState('')
  
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    address: '',
    city: '',
    country: 'España',
    zipCode: '',
    description: '',
    website: '',
    instagram: '',
    centerType: '',
    plan: 'starter',
  })

  useEffect(() => {
    const checkAuth = async () => {
      const { data } = await supabase.auth.getSession()
      if (!data.session) {
        router.push('/center-owner/login')
      } else {
        setUser(data.session.user)
      }
    }
    checkAuth()
  }, [])

  const handleInputChange = (e: any) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
  }

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    setUploading(true)
    try {
      const filename = `${Date.now()}_${file.name}`
      const { error } = await supabase.storage
        .from('center-logos')
        .upload(filename, file)

      if (error) {
        alert('Error al subir el archivo')
      } else {
        const { data } = supabase.storage
          .from('center-logos')
          .getPublicUrl(filename)
        setLogoUrl(data.publicUrl)
      }
    } catch (err) {
      console.error('Error uploading file:', err)
    } finally {
      setUploading(false)
    }
  }

  const handleCreateCenter = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)

    try {
      if (!user) return

      const { data, error } = await supabase
        .from('centers')
        .insert({
          owner_id: user.id,
          name: formData.name,
          email: formData.email,
          phone: formData.phone,
          address: formData.address,
          city: formData.city,
          country: formData.country,
          zip_code: formData.zipCode,
          description: formData.description,
          website: formData.website,
          instagram: formData.instagram,
          center_type: formData.centerType,
          plan: formData.plan,
          logo_url: logoUrl,
          status: 'active',
        })
        .select()

      if (error) {
        alert('Error al crear el centro: ' + error.message)
      } else {
        if (data && data[0]) {
          router.push(`/center/${data[0].id}`)
        } else {
          router.push('/center-owner/centers')
        }
      }
    } catch (err) {
      console.error('Error:', err)
      alert('Error al crear el centro')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen bg-black">
      {/* Header */}
      <div className="border-b border-white/10 bg-black px-8 py-6">
        <div className="max-w-4xl mx-auto">
          <Link href="/center-owner/centers" className="flex items-center gap-2 text-gray-400 hover:text-white mb-4 transition-colors">
            <ArrowLeft size={18} /> Volver
          </Link>
          <h1 className="text-4xl font-heading font-bold text-white">Crear Nuevo Centro</h1>
        </div>
      </div>

      {/* Content */}
      <div className="max-w-4xl mx-auto px-8 py-12">
        <form onSubmit={handleCreateCenter} className="space-y-12">
          {/* Logo Section */}
          <div>
            <h2 className="text-2xl font-bold text-white mb-6">Logo del Centro</h2>
            <div className="rounded-xl border-2 border-dashed border-white/20 p-8 text-center hover:border-brand-red/50 transition-all">
              {logoUrl ? (
                <div className="mb-4">
                  <img src={logoUrl} alt="Logo" className="w-24 h-24 mx-auto rounded-lg object-cover" />
                </div>
              ) : (
                <div className="text-5xl mb-4">🏢</div>
              )}
              <p className="text-gray-400 mb-4">Arrastra tu logo aquí o haz clic para seleccionar</p>
              <label className="inline-flex items-center gap-2 rounded-lg bg-brand-red/20 hover:bg-brand-red/30 px-4 py-2 text-brand-red font-bold cursor-pointer transition-all">
                <Upload size={18} /> Subir Logo
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFileUpload}
                  disabled={uploading}
                  className="hidden"
                />
              </label>
              {uploading && <p className="text-gray-400 mt-2 text-sm">Subiendo...</p>}
            </div>
          </div>

          {/* Basic Information */}
          <div>
            <h2 className="text-2xl font-bold text-white mb-6">Información del Centro</h2>
            <div className="space-y-6">
              <div>
                <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Nombre del Centro *</label>
                <input
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleInputChange}
                  required
                  className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                />
              </div>

              <div className="grid gap-6 md:grid-cols-2">
                <div>
                  <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Email *</label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    required
                    className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Teléfono</label>
                  <input
                    type="tel"
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Tipo de Centro *</label>
                <div className="grid grid-cols-3 md:grid-cols-5 gap-2">
                  {centerTypes.map((type) => (
                    <button
                      key={type.id}
                      type="button"
                      onClick={() => setFormData(prev => ({ ...prev, centerType: type.id }))}
                      className={`p-3 rounded-lg text-center transition-all ${
                        formData.centerType === type.id
                          ? 'border-2 border-brand-red bg-brand-red/20'
                          : 'border-2 border-white/10 hover:border-white/30 bg-white/5'
                      }`}
                      title={type.label}
                    >
                      <div className="text-2xl mb-1">{type.emoji}</div>
                      <div className="text-xs font-bold text-white">{type.label.split(' ')[0]}</div>
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Descripción</label>
                <textarea
                  name="description"
                  value={formData.description}
                  onChange={handleInputChange}
                  rows={4}
                  className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all resize-none"
                  placeholder="Describe tu centro..."
                />
              </div>
            </div>
          </div>

          {/* Location */}
          <div>
            <h2 className="text-2xl font-bold text-white mb-6">Ubicación</h2>
            <div className="space-y-6">
              <div>
                <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Dirección *</label>
                <input
                  type="text"
                  name="address"
                  value={formData.address}
                  onChange={handleInputChange}
                  required
                  className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                />
              </div>

              <div className="grid gap-6 md:grid-cols-3">
                <div>
                  <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Ciudad *</label>
                  <input
                    type="text"
                    name="city"
                    value={formData.city}
                    onChange={handleInputChange}
                    required
                    className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">País</label>
                  <input
                    type="text"
                    name="country"
                    value={formData.country}
                    onChange={handleInputChange}
                    className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Código Postal</label>
                  <input
                    type="text"
                    name="zipCode"
                    value={formData.zipCode}
                    onChange={handleInputChange}
                    className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                  />
                </div>
              </div>
            </div>
          </div>

          {/* Social & Web */}
          <div>
            <h2 className="text-2xl font-bold text-white mb-6">Web y Redes</h2>
            <div className="grid gap-6 md:grid-cols-2">
              <div>
                <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Sitio Web</label>
                <input
                  type="url"
                  name="website"
                  value={formData.website}
                  onChange={handleInputChange}
                  placeholder="www.tucentro.com"
                  className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-gray-400 uppercase tracking-widest mb-2">Instagram</label>
                <input
                  type="text"
                  name="instagram"
                  value={formData.instagram}
                  onChange={handleInputChange}
                  placeholder="@tucentro"
                  className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                />
              </div>
            </div>
          </div>

          {/* Plan Selection */}
          <div>
            <h2 className="text-2xl font-bold text-white mb-6">Plan *</h2>
            <div className="grid gap-4 md:grid-cols-3">
              {plans.map((plan) => (
                <button
                  key={plan.id}
                  type="button"
                  onClick={() => setFormData(prev => ({ ...prev, plan: plan.id }))}
                  className={`p-6 rounded-lg border-2 transition-all text-left ${
                    formData.plan === plan.id
                      ? 'border-brand-red bg-brand-red/10'
                      : 'border-white/10 hover:border-white/30 bg-white/5'
                  }`}
                >
                  <div className="font-bold text-white mb-1">{plan.name}</div>
                  <div className="text-2xl font-bold text-brand-red mb-2">{plan.price}</div>
                  <div className="text-xs text-gray-400">{plan.description}</div>
                </button>
              ))}
            </div>
          </div>

          {/* Buttons */}
          <div className="border-t border-white/10 pt-8 flex gap-4">
            <button
              type="submit"
              disabled={loading || !formData.centerType}
              className="flex-1 rounded-lg bg-brand-red hover:bg-brand-accent px-6 py-3 text-sm font-bold text-white transition-all shadow-lg hover:shadow-brand-red/20 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            >
              {loading ? (
                <>
                  <Loader2 size={18} className="animate-spin" />
                  Creando...
                </>
              ) : (
                'Crear Centro'
              )}
            </button>
            <Link
              href="/center-owner/centers"
              className="flex-1 rounded-lg bg-white/5 hover:bg-white/10 px-6 py-3 text-sm font-bold text-white transition-all text-center"
            >
              Cancelar
            </Link>
          </div>
        </form>
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { Plus, LogOut, Settings, Trash2, Edit2, Eye } from 'lucide-react'
import Link from 'next/link'
import Image from 'next/image'
import { createClient } from '@/utils/supabase/client'
import { useRouter } from 'next/navigation'

interface Center {
  id: string
  name: string
  city: string
  center_type: string
  status: string
  plan: string
  logo_url?: string
  members_count?: number
  revenue_month?: number
}

export default function OwnerCenters() {
  const router = useRouter()
  const supabase = createClient()
  
  const [centers, setCenters] = useState<Center[]>([])
  const [loading, setLoading] = useState(true)
  const [user, setUser] = useState<any>(null)

  useEffect(() => {
    const checkAuth = async () => {
      const { data } = await supabase.auth.getSession()
      
      if (!data.session) {
        router.push('/center-owner/login')
        return
      }

      setUser(data.session.user)
      fetchCenters(data.session.user.id)
    }

    checkAuth()
  }, [])

  const fetchCenters = async (ownerId: string) => {
    try {
      const { data, error } = await supabase
        .from('centers')
        .select('*')
        .eq('owner_id', ownerId)
        .order('created_at', { ascending: false })

      if (error) {
        console.error('Error fetching centers:', error)
      } else {
        setCenters(data || [])
      }
    } catch (err) {
      console.error('Error:', err)
    } finally {
      setLoading(false)
    }
  }

  const handleLogout = async () => {
    await supabase.auth.signOut()
    router.push('/center-owner/login')
  }

  const handleDeleteCenter = async (centerId: string) => {
    if (confirm('¿Estás seguro de que deseas eliminar este centro?')) {
      const { error } = await supabase
        .from('centers')
        .delete()
        .eq('id', centerId)

      if (error) {
        alert('Error al eliminar el centro')
      } else {
        setCenters(centers.filter(c => c.id !== centerId))
      }
    }
  }

  return (
    <div className="min-h-screen bg-black">
      {/* Header */}
      <div className="border-b border-white/10 bg-black px-8 py-6">
        <div className="max-w-7xl mx-auto">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-4xl font-heading font-bold text-white mb-1">Mis Centros</h1>
              <p className="text-gray-400">{user?.email}</p>
            </div>
            <div className="flex items-center gap-4">
              <Link
                href="/center-owner/centers/new"
                className="flex items-center gap-2 rounded-lg bg-brand-red hover:bg-brand-accent px-6 py-3 text-sm font-bold text-white transition-all shadow-lg hover:shadow-brand-red/20"
              >
                <Plus size={18} /> Nuevo Centro
              </Link>
              <button
                onClick={handleLogout}
                className="flex items-center gap-2 rounded-lg bg-white/5 hover:bg-white/10 px-6 py-3 text-sm font-bold text-white transition-all"
              >
                <LogOut size={18} /> Salir
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="max-w-7xl mx-auto px-8 py-12">
        {loading ? (
          <div className="text-center text-gray-400">Cargando centros...</div>
        ) : centers.length === 0 ? (
          <div className="text-center py-12">
            <div className="text-5xl mb-4">🏢</div>
            <h2 className="text-2xl font-bold text-white mb-2">No tienes centros</h2>
            <p className="text-gray-400 mb-6">Crea tu primer centro para empezar</p>
            <Link
              href="/center-owner/centers/new"
              className="inline-flex items-center gap-2 rounded-lg bg-brand-red hover:bg-brand-accent px-6 py-3 text-sm font-bold text-white transition-all"
            >
              <Plus size={18} /> Crear Centro
            </Link>
          </div>
        ) : (
          <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
            {centers.map((center) => (
              <div key={center.id} className="rounded-xl border border-white/10 bg-white/5 overflow-hidden hover:border-brand-red/30 transition-all">
                {/* Header */}
                <div className="bg-gradient-to-r from-brand-red/20 to-transparent p-4 h-24 flex items-end relative">
                  <div className="absolute top-3 right-3 flex gap-2">
                    <Link
                      href={`/center/${center.id}`}
                      className="p-2 rounded-lg bg-white/10 hover:bg-brand-red/20 transition-all"
                      title="Ver dashboard"
                    >
                      <Eye size={18} className="text-white" />
                    </Link>
                    <Link
                      href={`/center-owner/centers/${center.id}/edit`}
                      className="p-2 rounded-lg bg-white/10 hover:bg-brand-red/20 transition-all"
                      title="Editar"
                    >
                      <Edit2 size={18} className="text-white" />
                    </Link>
                    <button
                      onClick={() => handleDeleteCenter(center.id)}
                      className="p-2 rounded-lg bg-white/10 hover:bg-red-500/20 transition-all"
                      title="Eliminar"
                    >
                      <Trash2 size={18} className="text-red-500" />
                    </button>
                  </div>
                  <div className="text-3xl">{center.logo_url ? '🏢' : '🏋️'}</div>
                </div>

                {/* Body */}
                <div className="p-6">
                  <h3 className="text-lg font-bold text-white mb-1">{center.name}</h3>
                  <p className="text-sm text-gray-400 mb-4">
                    📍 {center.city}, {center.center_type}
                  </p>

                  <div className="space-y-2 mb-4">
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-gray-400">Plan</span>
                      <span className="px-3 py-1 rounded-full bg-brand-red/20 text-brand-red text-xs font-bold uppercase">
                        {center.plan}
                      </span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-gray-400">Estado</span>
                      <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase ${
                        center.status === 'active'
                          ? 'bg-green-500/20 text-green-400'
                          : 'bg-gray-500/20 text-gray-400'
                      }`}>
                        {center.status === 'active' ? 'Activo' : 'Inactivo'}
                      </span>
                    </div>
                  </div>

                  <Link
                    href={`/center/${center.id}`}
                    className="w-full py-2 rounded-lg bg-brand-red hover:bg-brand-accent text-white font-bold text-sm transition-all text-center block"
                  >
                    Ir al Dashboard
                  </Link>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { Mail, Lock, ArrowRight, AlertCircle, Loader2 } from 'lucide-react'
import Link from 'next/link'
import Image from 'next/image'
import { createClient } from '@/utils/supabase/client'
import { useRouter } from 'next/navigation'

export default function CenterOwnerLogin() {
  const router = useRouter()
  const supabase = createClient()
  
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const [mode, setMode] = useState<'login' | 'signup'>('login')

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    setLoading(true)

    try {
      if (mode === 'login') {
        const { data, error: authError } = await supabase.auth.signInWithPassword({
          email,
          password,
        })
        
        if (authError) {
          setError(authError.message)
          return
        }

        if (data.user) {
          // Redirect to centers list
          router.push('/center-owner/centers')
        }
      } else {
        const { data, error: authError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            emailRedirectTo: `${location.origin}/auth/callback`,
          },
        })

        if (authError) {
          setError(authError.message)
          return
        }

        if (data.user) {
          // Create user profile
          const { error: profileError } = await supabase
            .from('users')
            .insert({
              id: data.user.id,
              email: data.user.email,
              role: 'center_owner',
            })

          if (profileError) {
            console.error('Error creating profile:', profileError)
          }

          setError('Cuenta creada. Por favor verifica tu email para continuar.')
          setMode('login')
        }
      }
    } catch (err) {
      setError('Ocurrió un error. Intenta de nuevo.')
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen bg-black flex font-sans selection:bg-brand-red selection:text-white">
      <div className="hidden lg:flex w-1/2 relative overflow-hidden items-center justify-center">
        <Image src="/assets/hero-cinematic.png" alt="Fitness center" fill className="object-cover opacity-60" />
        <div className="absolute inset-0 bg-gradient-to-r from-black/50 to-black pointer-events-none" />
        <div className="absolute bottom-12 left-12 z-10">
          <h2 className="text-5xl font-heading font-bold text-white mb-4">Gestiona tu <br /><span className="text-brand-red">Centro Fitness</span></h2>
          <p className="text-gray-400 max-w-md text-lg">Panel de control para propietarios. Clases, miembros, ingresos y más.</p>
        </div>
      </div>

      <div className="w-full lg:w-1/2 flex items-center justify-center p-8 relative">
        <div className="max-w-md w-full">
          <div className="mb-10">
            <Image src="/logo.svg" alt="Rival" width={40} height={40} className="mb-6 w-10 h-10" />
            <h1 className="text-4xl font-heading font-bold text-white mb-2">
              {mode === 'login' ? 'Inicia Sesión' : 'Crea tu Cuenta'}
            </h1>
            <p className="text-gray-400">Acceso para propietarios de centros</p>
          </div>

          {error && (
            <div className={`flex gap-2 p-3 rounded-xl text-sm mb-6 ${
              error.includes('verificar')
                ? 'bg-blue-500/10 border border-blue-500/50 text-blue-400'
                : 'bg-red-500/10 border border-red-500/50 text-red-400'
            }`}>
              <AlertCircle size={18} className="flex-shrink-0 mt-0.5" />
              <span>{error}</span>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-2">Email</label>
              <div className="relative group">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-500 group-focus-within:text-brand-red transition-colors" />
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full bg-brand-gray border border-white/10 rounded-xl py-4 pl-12 pr-4 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all placeholder:text-gray-600"
                  placeholder="tu@email.com"
                  required
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-2">Contraseña</label>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-500 group-focus-within:text-brand-red transition-colors" />
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-brand-gray border border-white/10 rounded-xl py-4 pl-12 pr-4 text-white focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all placeholder:text-gray-600"
                  placeholder="••••••••"
                  required
                />
              </div>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-brand-red hover:bg-brand-accent text-white py-4 rounded-xl font-bold text-lg transition-all shadow-lg hover:shadow-brand-red/20 flex items-center justify-center gap-2 group disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? (
                <>
                  <Loader2 size={20} className="animate-spin" />
                  {mode === 'login' ? 'Iniciando...' : 'Creando...'}
                </>
              ) : (
                <>
                  {mode === 'login' ? 'Iniciar Sesión' : 'Crear Cuenta'}
                  <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                </>
              )}
            </button>
          </form>

          <div className="mt-8 text-center border-t border-white/5 pt-6">
            <p className="text-gray-500 mb-4">
              {mode === 'login' ? '¿No tienes cuenta?' : '¿Ya tienes cuenta?'}
            </p>
            <button
              onClick={() => {
                setMode(mode === 'login' ? 'signup' : 'login')
                setError('')
              }}
              className="text-brand-red font-bold hover:text-brand-accent transition-colors"
            >
              {mode === 'login' ? 'Regístrate aquí' : 'Inicia sesión aquí'}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

"use client";

import { useState, useEffect } from "react";
import { Bell, X, CheckCircle2, Swords, UserPlus, Zap } from "lucide-react";
import { getNotifications, markAsRead } from "./notifications-actions";
import clsx from "clsx";
import Link from "next/link";

export default function NotificationBell() {
    const [notifications, setNotifications] = useState<any[]>([]);
    const [isOpen, setIsOpen] = useState(false);
    const [unreadCount, setUnreadCount] = useState(0);

    useEffect(() => {
        async function loadNotifications() {
            const data = await getNotifications();
            setNotifications(data);
            setUnreadCount(data.filter((n: any) => !n.is_read).length);
        }
        loadNotifications();

        // Refresh every 60 seconds
        const interval = setInterval(loadNotifications, 60000);
        return () => clearInterval(interval);
    }, []);

    const handleMarkAsRead = async (id: string) => {
        await markAsRead(id);
        setNotifications(prev => prev.map(n => n.id === id ? { ...n, is_read: true } : n));
        setUnreadCount(prev => Math.max(0, prev - 1));
    };

    const getTypeIcon = (type: string) => {
        switch (type) {
            case 'duel_challenge': return <Swords className="w-4 h-4 text-brand-red" />;
            case 'follow': return <UserPlus className="w-4 h-4 text-blue-500" />;
            case 'mission_complete': return <CheckCircle2 className="w-4 h-4 text-green-500" />;
            default: return <Zap className="w-4 h-4 text-yellow-500" />;
        }
    };

    return (
        <div className="relative">
            <button
                onClick={() => setIsOpen(!isOpen)}
                className="relative p-2 text-gray-400 hover:text-white transition-colors"
            >
                <Bell className="w-6 h-6" />
                {unreadCount > 0 && (
                    <span className="absolute top-1 right-1 w-4 h-4 bg-brand-red text-white text-[10px] font-bold rounded-full flex items-center justify-center border-2 border-black">
                        {unreadCount}
                    </span>
                )}
            </button>

            {isOpen && (
                <>
                    <div
                        className="fixed inset-0 z-40"
                        onClick={() => setIsOpen(false)}
                    />
                    <div className="absolute right-0 mt-4 w-80 bg-brand-gray border border-white/10 rounded-2xl shadow-2xl z-50 overflow-hidden">
                        <div className="p-4 border-b border-white/5 flex items-center justify-between">
                            <h3 className="text-xs font-black uppercase tracking-widest text-white">Notifications</h3>
                            <button onClick={() => setIsOpen(false)} className="text-gray-500 hover:text-white">
                                <X className="w-4 h-4" />
                            </button>
                        </div>
                        <div className="max-h-96 overflow-y-auto">
                            {notifications.length > 0 ? (
                                notifications.map((n) => (
                                    <div
                                        key={n.id}
                                        className={clsx(
                                            "p-4 border-b border-white/5 hover:bg-white/5 transition-colors cursor-pointer relative",
                                            !n.is_read ? "bg-brand-red/[0.03]" : ""
                                        )}
                                        onClick={() => {
                                            if (!n.is_read) handleMarkAsRead(n.id);
                                            if (n.link) window.location.href = n.link;
                                        }}
                                    >
                                        <div className="flex gap-3">
                                            <div className="mt-1">{getTypeIcon(n.type)}</div>
                                            <div className="flex-1 min-w-0">
                                                <p className={clsx("text-xs text-white", !n.is_read ? "font-black" : "font-medium")}>
                                                    {n.title}
                                                </p>
                                                <p className="text-[10px] text-gray-500 mt-0.5 line-clamp-2">{n.content}</p>
                                                <p className="text-[8px] text-gray-600 mt-2 font-bold uppercase tracking-tighter">
                                                    {new Date(n.created_at).toLocaleDateString()}
                                                </p>
                                            </div>
                                            {!n.is_read && (
                                                <div className="w-1.5 h-1.5 rounded-full bg-brand-red mt-1" />
                                            )}
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <div className="p-8 text-center text-gray-600 text-[10px] font-black uppercase tracking-widest">
                                    No incoming signals.
                                </div>
                            )}
                        </div>
                        {notifications.length > 0 && (
                            <Link
                                href="/dashboard/notifications"
                                className="block p-3 text-center bg-black/40 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] hover:text-white transition-colors"
                            >
                                View All Signals
                            </Link>
                        )}
                    </div>
                </>
            )}
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { getDetailedAnalytics, getPerformanceStats } from "../training/actions";
import {
    BarChart2,
    TrendingUp,
    Activity,
    Zap,
    Award,
    Calendar,
    PieChart,
    ChevronRight,
    ArrowUpRight,
    ArrowDownRight,
    Trophy
} from "lucide-react";
import clsx from "clsx";

export default function AnalyticsPage() {
    const [stats, setStats] = useState<any>(null);
    const [weeklyStats, setWeeklyStats] = useState<any>(null);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        async function loadData() {
            const [detailed, weekly] = await Promise.all([
                getDetailedAnalytics(),
                getPerformanceStats()
            ]);
            setStats(detailed);
            setWeeklyStats(weekly);
            setIsLoading(false);
        }
        loadData();
    }, []);

    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4">
                <div className="w-12 h-12 border-4 border-brand-red border-t-transparent rounded-full animate-spin"></div>
                <p className="text-gray-500 font-bold uppercase tracking-widest text-xs">Synchronizing Performance Metrics...</p>
            </div>
        );
    }

    const muscleLabels = Object.keys(stats.muscleGroups || {});
    const muscleValues = Object.values(stats.muscleGroups || {}) as number[];
    const maxMuscleVolume = Math.max(...muscleValues, 1);

    return (
        <div className="space-y-10 pb-20">
            {/* Header section */}
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div>
                    <h1 className="text-4xl font-heading font-black text-white glow-text mb-2 tracking-tighter uppercase italic">Performance Radar</h1>
                    <p className="text-gray-500 max-w-md">Detailed biological and strength data harvested from your recent missions.</p>
                </div>
                <div className="flex gap-4">
                    <div className="bg-brand-gray border border-white/5 p-4 rounded-2xl">
                        <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest mb-1">Weekly Readiness</p>
                        <div className="flex items-center gap-2">
                            <Zap className={clsx("w-4 h-4", weeklyStats.fatigue > 80 ? "text-brand-red" : "text-green-500")} />
                            <span className="text-xl font-heading font-black text-white">{100 - weeklyStats.fatigue}%</span>
                        </div>
                    </div>
                    <div className="bg-brand-gray border border-white/5 p-4 rounded-2xl">
                        <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest mb-1">Consistency</p>
                        <div className="flex items-center gap-2">
                            <Calendar className="w-4 h-4 text-brand-red" />
                            <span className="text-xl font-heading font-black text-white">{stats.weeklyFreq[3]}x <span className="text-[10px] text-gray-500">Wk</span></span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Quick Stats Grid */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
                <MetricCard
                    label="Total Volume (7d)"
                    value={`${weeklyStats.daily.reduce((acc: number, s: any) => acc + s.total_volume_kg, 0).toLocaleString()} kg`}
                    trend="+12%"
                    up
                />
                <MetricCard
                    label="Avg Intensity"
                    value={`RPE ${(weeklyStats.daily.reduce((acc: number, s: any) => acc + (s.effort_rpe || 0), 0) / (weeklyStats.daily.length || 1)).toFixed(1)}`}
                    trend="Stable"
                />
                <MetricCard
                    label="PRs Broken (28d)"
                    value={stats.prHistory.length}
                    trend={`+${stats.prHistory.filter((pr: any) => new Date(pr.created_at) > new Date(Date.now() - 7 * 24 * 60 * 60 * 1000)).length} new`}
                    up
                />
                <MetricCard
                    label="Training Points"
                    value={`${(weeklyStats.daily.length * 150).toLocaleString()}`}
                    trend="Earned"
                />
            </div>

            <div className="grid lg:grid-cols-3 gap-8">
                {/* Volume Progression Chart */}
                <div className="lg:col-span-2 bg-brand-gray border border-white/5 rounded-3xl p-8 relative overflow-hidden group">
                    <div className="absolute top-0 right-0 p-8 text-white/5 group-hover:text-brand-red/5 transition-colors">
                        <TrendingUp className="w-32 h-32" />
                    </div>
                    <div className="relative z-10">
                        <h3 className="text-lg font-heading font-bold text-white mb-8 flex items-center gap-2 uppercase italic tracking-widest">
                            <Activity className="w-5 h-5 text-brand-red" /> Volume Protocol (7 Days)
                        </h3>
                        <div className="flex items-end gap-3 h-64">
                            {weeklyStats.daily.map((s: any, i: number) => (
                                <div key={i} className="flex-1 flex flex-col items-center gap-4 group/bar relative">
                                    {/* Tooltip */}
                                    <div className="absolute -top-12 bg-white text-black text-[10px] font-black px-2 py-1 rounded opacity-0 group-hover/bar:opacity-100 transition-opacity whitespace-nowrap">
                                        {s.total_volume_kg} KG
                                    </div>
                                    <div
                                        className="w-full bg-brand-red/10 border border-brand-red/20 rounded-t-xl transition-all group-hover/bar:bg-brand-red group-hover/bar:shadow-[0_0_30px_rgba(220,38,38,0.4)]"
                                        style={{ height: `${(s.total_volume_kg / Math.max(...weeklyStats.daily.map((x: any) => x.total_volume_kg), 1)) * 100}%` }}
                                    />
                                    <div className="text-[10px] text-gray-500 font-black uppercase tracking-widest">
                                        {new Date(s.created_at).toLocaleDateString('es-ES', { weekday: 'short' })}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Muscle Distribution */}
                <div className="bg-brand-gray border border-white/5 rounded-3xl p-8">
                    <h3 className="text-lg font-heading font-bold text-white mb-8 flex items-center gap-2 uppercase italic tracking-widest">
                        <PieChart className="w-5 h-5 text-brand-red" /> Muscle Focus
                    </h3>
                    <div className="space-y-6">
                        {muscleLabels.length > 0 ? muscleLabels.map((label, idx) => (
                            <div key={label} className="space-y-2">
                                <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest">
                                    <span className="text-gray-400">{label}</span>
                                    <span className="text-white">{Math.round((muscleValues[idx] / muscleValues.reduce((a, b) => a + b, 0)) * 100)}%</span>
                                </div>
                                <div className="h-2 w-full bg-black/40 rounded-full overflow-hidden border border-white/5">
                                    <div
                                        className="h-full bg-brand-red shadow-[0_0_10px_rgba(220,38,38,0.3)] transition-all duration-1000"
                                        style={{ width: `${(muscleValues[idx] / maxMuscleVolume) * 100}%` }}
                                    />
                                </div>
                            </div>
                        )) : (
                            <div className="text-center py-20 text-gray-600 text-[10px] font-black uppercase tracking-[0.2em]">No focus data available</div>
                        )}
                    </div>
                </div>
            </div>

            {/* PR History & Weekly Frequency */}
            <div className="grid lg:grid-cols-2 gap-8">
                {/* PR History */}
                <div className="bg-brand-gray border border-white/5 rounded-3xl p-8 overflow-hidden relative">
                    <Trophy className="absolute -right-10 -bottom-10 w-48 h-48 text-brand-red/5 -rotate-12" />
                    <h3 className="text-lg font-heading font-bold text-white mb-8 flex items-center gap-2 uppercase italic tracking-widest">
                        <Award className="w-5 h-5 text-yellow-500" /> Recent Breakthroughs
                    </h3>
                    <div className="space-y-4 relative z-10">
                        {stats.prHistory.length > 0 ? stats.prHistory.map((pr: any, i: number) => (
                            <div key={i} className="flex items-center justify-between p-4 bg-black/40 border border-white/5 rounded-2xl hover:border-brand-red/30 transition-colors group">
                                <div className="flex items-center gap-4">
                                    <div className="w-10 h-10 bg-brand-red/10 rounded-xl flex items-center justify-center text-brand-red border border-brand-red/20 group-hover:bg-brand-red group-hover:text-white transition-colors">
                                        <Trophy className="w-5 h-5" />
                                    </div>
                                    <div>
                                        <p className="text-white font-bold text-sm tracking-tight">{pr.exercise_name}</p>
                                        <p className="text-[10px] text-gray-500 uppercase font-black tracking-widest">{new Date(pr.created_at).toLocaleDateString()}</p>
                                    </div>
                                </div>
                                <div className="text-right">
                                    <p className="text-xl font-heading font-black text-white">{pr.weight_kg} <span className="text-[10px] text-gray-500">KG</span></p>
                                    <span className="text-[8px] bg-green-500/10 text-green-500 px-2 py-0.5 rounded font-black uppercase tracking-tighter">NEW RECORD</span>
                                </div>
                            </div>
                        )) : (
                            <div className="text-center py-20 text-gray-600 text-[10px] font-black uppercase tracking-[0.2em]">No PRs detected yet</div>
                        )}
                    </div>
                </div>

                {/* Weekly Frequency */}
                <div className="bg-brand-gray border border-white/5 rounded-3xl p-8">
                    <h3 className="text-lg font-heading font-bold text-white mb-8 flex items-center gap-2 uppercase italic tracking-widest">
                        <BarChart2 className="w-5 h-5 text-brand-red" /> Mission Frequency
                    </h3>
                    <div className="flex justify-between items-end h-64 px-4">
                        {stats.weeklyFreq.map((count: number, i: number) => {
                            const labels = ["W-3", "W-2", "W-1", "NOW"];
                            return (
                                <div key={i} className="flex flex-col items-center gap-4 group/freq">
                                    <div className="text-[10px] text-white font-black">{count}x</div>
                                    <div
                                        className={clsx(
                                            "w-12 rounded-xl transition-all duration-500",
                                            i === 3 ? "bg-brand-red shadow-[0_0_20px_rgba(220,38,38,0.3)]" : "bg-white/5 border border-white/10"
                                        )}
                                        style={{ height: `${Math.max((count / 7) * 100, 10)}%` }}
                                    />
                                    <div className="text-[10px] text-gray-500 font-extrabold">{labels[i]}</div>
                                </div>
                            )
                        })}
                    </div>
                    <div className="mt-10 p-4 bg-white/5 border border-white/10 rounded-2xl flex items-center justify-between">
                        <div>
                            <p className="text-xs text-white font-bold uppercase tracking-tight">Active Streak</p>
                            <p className="text-[10px] text-gray-500">You are more active than 85% of Rivals.</p>
                        </div>
                        <button className="text-brand-red flex items-center gap-1 text-[10px] font-black uppercase tracking-widest hover:translate-x-1 transition-transform">
                            Full Log <ChevronRight className="w-3 h-3" />
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

function MetricCard({ label, value, trend, up }: { label: string, value: string | number, trend: string, up?: boolean }) {
    return (
        <div className="bg-brand-gray border border-white/5 p-6 rounded-3xl group hover:border-brand-red/30 transition-all">
            <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest mb-2">{label}</p>
            <div className="flex items-end justify-between">
                <h4 className="text-2xl font-heading font-black text-white">{value}</h4>
                <div className={clsx(
                    "flex items-center text-[10px] font-bold px-2 py-0.5 rounded-full",
                    up ? "text-green-500 bg-green-500/10" : "text-gray-400 bg-white/5"
                )}>
                    {up ? <ArrowUpRight className="w-3 h-3 mr-0.5" /> : null}
                    {trend}
                </div>
            </div>
        </div>
    )
}

"use client";

import { useState, useRef, useEffect } from "react";
import Image from "next/image";
import { Send, Bot, User as UserIcon, Loader2, Dumbbell, PlayCircle, BarChart2, Calendar, Activity, TrendingUp, Award } from "lucide-react";
import clsx from "clsx";
import Link from "next/link";

import { getRecentPRs, getUserProfile, getPerformanceStats, scheduleWorkout } from "../training/actions";

interface Message {
    id: string;
    role: 'user' | 'assistant';
    content: string;
    workout?: any; // Structured workout data if available
}

export default function CoachPage() {
    const [messages, setMessages] = useState<Message[]>([
        {
            id: '1',
            role: 'assistant',
            content: "Welcome, Soldier. I am your Online Coach. I've analyzed your recent performance. Ready to push your limits? What are we destroying today? Legs, Push, or Pull?",
        }
    ]);
    const [input, setInput] = useState("");
    const [isTyping, setIsTyping] = useState(false);
    const [profile, setProfile] = useState<any>(null);
    const [prs, setPrs] = useState<any[]>([]);
    const [stats, setStats] = useState<any>({ daily: [], fatigue: 0 });
    const [activeTab, setActiveTab] = useState<'chat' | 'insights'>('chat');
    const [isScheduling, setIsScheduling] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        async function loadData() {
            const [p, r, s] = await Promise.all([
                getUserProfile(),
                getRecentPRs(),
                getPerformanceStats()
            ]);
            setProfile(p);
            setPrs(r);
            setStats(s);
        }
        loadData();
    }, []);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        scrollToBottom();
    }, [messages]);

    const handleSend = async (customInput?: string) => {
        const messageText = customInput || input;
        if (!messageText.trim()) return;

        const userMsg: Message = {
            id: Date.now().toString(),
            role: 'user',
            content: messageText
        };

        setMessages(prev => [...prev, userMsg]);
        setInput("");
        setIsTyping(true);

        // Simulate AI thinking
        setTimeout(() => {
            let replyText = `Soldier, stay focused. We have records to break. Your current level is ${profile?.level || 'Beginner'}. Try 'Legs', 'Push', or 'Pull'.`;
            let workoutData = null;
            const lowerInput = messageText.toLowerCase();

            if (lowerInput.includes('leg') || lowerInput.includes('lower')) {
                replyText = `Leg Day Protocol activated. Your level is ${profile?.level}. Based on your history, let's smash some PRs today.`;
                workoutData = {
                    title: "Leg Destruction Protocol",
                    duration: "60 min",
                    intensity: "Extreme",
                    exercises: [
                        { name: "Back Squat", sets: "4", reps: "8-10" },
                        { name: "Romanian Deadlift", sets: "3", reps: "12" },
                        { name: "Leg Press", sets: "3", reps: "15" },
                        { name: "Walking Lunges", sets: "3", reps: "20 steps" }
                    ]
                };
            } else if (lowerInput.includes('push') || lowerInput.includes('chest')) {
                replyText = `Push session initiated. Time to build that armor. ${profile?.level === 'Elite' ? 'Elite blocks require maximum intensity.' : 'Focus on perfect form.'}`;
                workoutData = {
                    title: "Push Power Builder",
                    duration: "55 min",
                    intensity: "High",
                    exercises: [
                        { name: "Bench Press", sets: "5", reps: "5" },
                        { name: "Overhead Press", sets: "4", reps: "8" },
                        { name: "Dumbbell Press", sets: "3", reps: "10-12" },
                        { name: "Lateral Raises", sets: "4", reps: "15" }
                    ]
                };
            } else if (lowerInput.includes('pull') || lowerInput.includes('back')) {
                const recentPR = prs[0]?.exercise_name || "Deadlift";
                replyText = `Pull session engaged. Wide back incoming. Let's see if we can match that PR you hit on ${recentPR}.`;
                workoutData = {
                    title: "Back Widow Maker",
                    duration: "60 min",
                    intensity: "High",
                    exercises: [
                        { name: "Deadlift", sets: "3", reps: "5" },
                        { name: "Pull Ups", sets: "4", reps: "failure" },
                        { name: "Barbell Row", sets: "4", reps: "10" },
                        { name: "Face Pulls", sets: "3", reps: "15" }
                    ]
                };
            }

            const botMsg: Message = {
                id: (Date.now() + 1).toString(),
                role: 'assistant',
                content: replyText,
                workout: workoutData
            };

            setMessages(prev => [...prev, botMsg]);
            setIsTyping(false);
        }, 1500);
    };

    const handleSchedule = async (workout: any) => {
        setIsScheduling(true);
        const today = new Date().toISOString().split('T')[0];
        const res = await scheduleWorkout({
            title: workout.title,
            date: today,
            exercises: workout.exercises
        });
        setIsScheduling(false);
        if (res.success) {
            alert("Mission assigned to your calendar, Soldier!");
        }
    };

    return (
        <div className="h-[calc(100vh-140px)] flex flex-col bg-brand-gray border border-white/5 rounded-2xl overflow-hidden shadow-2xl">
            {/* Chat Header */}
            <div className="p-4 border-b border-white/5 bg-black/40 backdrop-blur-md flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-brand-red flex items-center justify-center shadow-[0_0_15px_rgba(220,38,38,0.5)]">
                        <Bot className="w-6 h-6 text-white" />
                    </div>
                    <div>
                        <h2 className="font-heading font-bold text-white text-lg leading-none">Coach Online</h2>
                        <p className="text-xs text-brand-red font-bold uppercase tracking-widest">Rival AI Assistant</p>
                    </div>
                </div>

                <div className="flex bg-white/5 rounded-lg p-1 border border-white/10">
                    <button
                        onClick={() => setActiveTab('chat')}
                        className={clsx("px-3 py-1.5 rounded-md text-[10px] font-black uppercase tracking-widest transition-all", activeTab === 'chat' ? "bg-brand-red text-white" : "text-gray-500 hover:text-white")}
                    >
                        Chat
                    </button>
                    <button
                        onClick={() => setActiveTab('insights')}
                        className={clsx("px-3 py-1.5 rounded-md text-[10px] font-black uppercase tracking-widest transition-all", activeTab === 'insights' ? "bg-brand-red text-white" : "text-gray-500 hover:text-white")}
                    >
                        Insights
                    </button>
                </div>
            </div>

            {activeTab === 'chat' ? (
                <>
                    {/* Messages Area */}
                    <div className="flex-1 overflow-y-auto p-4 space-y-6 scrollbar-thin scrollbar-thumb-brand-red/20 scrollbar-track-transparent">
                        {messages.map((msg) => (
                            <div
                                key={msg.id}
                                className={clsx(
                                    "flex gap-4 max-w-[85%]",
                                    msg.role === 'user' ? "ml-auto flex-row-reverse" : ""
                                )}
                            >
                                {/* Avatar */}
                                <div className={clsx(
                                    "w-8 h-8 rounded-full flex items-center justify-center shrink-0 mt-1",
                                    msg.role === 'user' ? "bg-gray-700" : "bg-brand-red"
                                )}>
                                    {msg.role === 'user' ? <UserIcon className="w-4 h-4 text-white" /> : <Bot className="w-4 h-4 text-white" />}
                                </div>

                                {/* Content */}
                                <div className="space-y-2">
                                    <div className={clsx(
                                        "p-4 rounded-2xl text-sm leading-relaxed",
                                        msg.role === 'user'
                                            ? "bg-white text-black font-medium rounded-tr-none"
                                            : "bg-black/50 border border-white/10 text-gray-200 rounded-tl-none"
                                    )}>
                                        {msg.content}
                                    </div>

                                    {/* Optional Workout Card Attachment */}
                                    {msg.workout && (
                                        <div className="bg-black border border-brand-red/30 rounded-xl overflow-hidden shadow-[0_4px_20px_rgba(220,38,38,0.1)] w-80">
                                            <div className="bg-brand-red/10 p-4 border-b border-brand-red/10 flex justify-between items-center">
                                                <div className="flex items-center gap-2">
                                                    <Dumbbell className="w-4 h-4 text-brand-red" />
                                                    <span className="font-bold text-white text-sm">{msg.workout.title}</span>
                                                </div>
                                                <span className="text-xs bg-brand-red text-white px-2 py-0.5 rounded font-bold uppercase">{msg.workout.duration}</span>
                                            </div>
                                            <div className="p-4 space-y-3">
                                                {msg.workout.exercises.map((ex: any, idx: number) => (
                                                    <div key={idx} className="flex justify-between text-xs border-b border-white/5 pb-2 last:border-0 last:pb-0">
                                                        <span className="text-gray-300">{ex.name}</span>
                                                        <span className="text-gray-500 font-mono">{ex.sets} x {ex.reps}</span>
                                                    </div>
                                                ))}
                                            </div>
                                            <div className="p-3 bg-white/5 border-t border-white/5 grid grid-cols-2 gap-2">
                                                <Link
                                                    href={`/dashboard/training/session`}
                                                    className="flex items-center justify-center gap-2 bg-white text-black py-2 rounded-lg text-[10px] font-black uppercase transition-colors hover:bg-brand-red hover:text-white"
                                                >
                                                    <PlayCircle className="w-3 h-3" /> Start Now
                                                </Link>
                                                <button
                                                    onClick={() => handleSchedule(msg.workout)}
                                                    disabled={isScheduling}
                                                    className="flex items-center justify-center gap-2 bg-brand-red/20 border border-brand-red/30 text-white py-2 rounded-lg text-[10px] font-black uppercase transition-colors hover:bg-brand-red disabled:opacity-50"
                                                >
                                                    <Calendar className="w-3 h-3" /> To Calendar
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}

                        {isTyping && (
                            <div className="flex gap-4 max-w-[85%]">
                                <div className="w-8 h-8 rounded-full bg-brand-red flex items-center justify-center shrink-0 mt-1">
                                    <Bot className="w-4 h-4 text-white" />
                                </div>
                                <div className="bg-black/50 border border-white/10 text-gray-200 rounded-2xl rounded-tl-none p-4 flex items-center gap-2">
                                    <Loader2 className="w-4 h-4 animate-spin text-brand-red" />
                                    <span className="text-xs text-gray-400">Analyzing metrics...</span>
                                </div>
                            </div>
                        )}
                        <div ref={messagesEndRef} />
                    </div>

                    {/* Quick Actions */}
                    <div className="px-4 py-2 flex gap-2 overflow-x-auto no-scrollbar bg-black/20 border-t border-white/5">
                        <QuickAction label="Lower Body" onClick={() => handleSend("Give me a Leg workout")} />
                        <QuickAction label="Push Day" onClick={() => handleSend("Build my chest and shoulders")} />
                        <QuickAction label="Pull Day" onClick={() => handleSend("Target my back and biceps")} />
                    </div>

                    {/* Input Area */}
                    <div className="p-4 bg-black border-t border-white/10">
                        <div className="relative flex items-center gap-2">
                            <input
                                type="text"
                                value={input}
                                onChange={(e) => setInput(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                                placeholder="Tell Coach what you want to train..."
                                className="w-full bg-brand-gray border border-white/10 text-white placeholder:text-gray-500 text-sm rounded-xl py-3 pl-4 pr-12 focus:outline-none focus:border-brand-red/50 focus:ring-1 focus:ring-brand-red/50 transition-all"
                            />
                            <button
                                onClick={() => handleSend()}
                                className="absolute right-2 p-2 bg-brand-red rounded-lg text-white hover:bg-red-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                                disabled={!input.trim() || isTyping}
                            >
                                <Send className="w-4 h-4" />
                            </button>
                        </div>
                        <div className="mt-2 text-center">
                            <p className="text-[10px] text-gray-600 uppercase tracking-widest font-bold">Rival Coach Online • AI Protocol 2.5</p>
                        </div>
                    </div>
                </>
            ) : (
                <div className="flex-1 overflow-y-auto p-8 space-y-10 bg-black/40">
                    <div className="grid md:grid-cols-2 gap-8">
                        <div className="bg-brand-gray/40 border border-white/5 p-6 rounded-3xl relative overflow-hidden group">
                            <div className="absolute top-0 right-0 p-4 text-brand-red/5 group-hover:text-brand-red/10 transition-colors">
                                <BarChart2 className="w-20 h-20" />
                            </div>
                            <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest mb-6 flex items-center gap-2">
                                <Activity className="w-3 h-3 text-brand-red" /> Volume Progression
                            </h3>

                            <div className="flex items-end gap-2 h-48 mt-4">
                                {stats.daily && stats.daily.length > 0 ? stats.daily.map((s: any, i: number) => (
                                    <div key={i} className="flex-1 flex flex-col items-center gap-2 group/bar">
                                        <div
                                            className="w-full bg-brand-red/20 border border-brand-red/30 rounded-t-lg transition-all group-hover/bar:bg-brand-red group-hover/bar:shadow-[0_0_15px_rgba(220,38,38,0.5)]"
                                            style={{ height: `${Math.min((s.total_volume_kg / 5000) * 100, 100)}%` }}
                                        />
                                        <span className="text-[8px] text-gray-600 font-bold uppercase">{new Date(s.created_at).toLocaleDateString('es-ES', { weekday: 'short' })}</span>
                                    </div>
                                )) : (
                                    <div className="w-full h-full flex items-center justify-center text-gray-500 text-[10px] uppercase font-bold">No sessions logged this week</div>
                                )}
                            </div>
                        </div>

                        <div className="space-y-6">
                            <div className="bg-brand-gray/40 border border-white/5 p-6 rounded-3xl">
                                <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest mb-4">Coach Insights</h3>
                                <div className="space-y-4">
                                    <div className="flex items-start gap-3">
                                        <div className="p-2 bg-green-500/10 rounded-lg">
                                            <TrendingUp className="w-4 h-4 text-green-500" />
                                        </div>
                                        <div>
                                            <p className="text-xs text-white font-bold italic uppercase tracking-tight">Consistency High</p>
                                            <p className="text-[10px] text-gray-500">You've hit {stats.daily?.length || 0} training zones this week. Performance is optimal.</p>
                                        </div>
                                    </div>
                                    <div className="flex items-start gap-3">
                                        <div className="p-2 bg-yellow-500/10 rounded-lg">
                                            <Award className="w-4 h-4 text-yellow-500" />
                                        </div>
                                        <div>
                                            <p className="text-xs text-white font-bold italic uppercase tracking-tight">{prs.length} PRs Reached</p>
                                            <p className="text-[10px] text-gray-500">Your strength levels are breaking previous limits. Keep pushing.</p>
                                        </div>
                                    </div>
                                    <div className="flex items-start gap-3">
                                        <div className="p-2 bg-brand-red/10 rounded-lg">
                                            <Dumbbell className="w-4 h-4 text-brand-red" />
                                        </div>
                                        <div>
                                            <p className="text-xs text-white font-bold italic uppercase tracking-tight">Volume Peak</p>
                                            <p className="text-[10px] text-gray-500">Last session reached {stats.daily?.[stats.daily.length - 1]?.total_volume_kg || 0}kg. Push for +5% tomorrow.</p>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="bg-brand-gray/40 border border-white/5 p-6 rounded-3xl">
                                <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest mb-4">Fatigue Protocol</h3>
                                <div className="space-y-4">
                                    <div className="flex justify-between items-end mb-2">
                                        <span className={clsx("text-xs font-black uppercase italic", stats.fatigue > 80 ? "text-brand-red" : stats.fatigue > 50 ? "text-yellow-500" : "text-green-500")}>
                                            {stats.fatigue > 80 ? "RECOVERY CRITICAL" : stats.fatigue > 50 ? "STRESS ACCUMULATING" : "OPTIMAL READINESS"}
                                        </span>
                                        <span className="text-[10px] text-gray-500 font-bold">{stats.fatigue}% ACCUMULATED</span>
                                    </div>
                                    <div className="h-2 w-full bg-white/5 rounded-full overflow-hidden border border-white/5">
                                        <div
                                            className={clsx("h-full transition-all duration-1000", stats.fatigue > 80 ? "bg-brand-red" : stats.fatigue > 50 ? "bg-yellow-500" : "bg-green-500")}
                                            style={{ width: `${stats.fatigue}%` }}
                                        />
                                    </div>
                                    <p className="text-[10px] text-gray-400 leading-relaxed italic">
                                        {stats.fatigue > 80
                                            ? "Command: Execute 24-48h rest protocol. Central Nervous System is overtaxed."
                                            : stats.fatigue > 50
                                                ? "Advise: Moderate intensity. Do not attempt 1RM today."
                                                : "Protocol: All systems nominal. Deploy maximum effort."}
                                    </p>
                                </div>
                            </div>

                            <div className="bg-gradient-to-br from-brand-red/20 to-black border border-brand-red/10 p-6 rounded-3xl">
                                <h3 className="text-[10px] font-black text-brand-red uppercase tracking-widest mb-2">Next Target</h3>
                                <p className="text-sm text-white font-bold mb-4">You are 4 sessions away from Elite Level tier.</p>
                                <button className="w-full py-3 bg-white text-black rounded-xl text-xs font-black uppercase tracking-widest hover:bg-brand-red hover:text-white transition-all">
                                    Reveal Strategy
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

function StatItem({ icon, label, value }: { icon: React.ReactNode, label: string, value: string }) {
    return (
        <div className="space-y-1">
            <div className="flex items-center gap-1.5 text-[10px] text-gray-500 font-bold uppercase tracking-widest">
                {icon} {label}
            </div>
            <p className="text-white font-black text-sm">{value}</p>
        </div>
    )
}

function QuickAction({ label, onClick }: { label: string, onClick: () => void }) {
    return (
        <button
            onClick={onClick}
            className="whitespace-nowrap bg-white/5 border border-white/10 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest text-gray-400 hover:text-white hover:bg-brand-red hover:border-brand-red transition-all"
        >
            {label}
        </button>
    )
}

'use server'

import { createClient } from "@/utils/supabase/server";
import { revalidatePath } from "next/cache";
import { createNotification } from "../notifications-actions";

export async function createDuel(opponentId: string) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return { error: "Not authenticated" };

    const startDate = new Date().toISOString().split('T')[0];
    const endDate = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

    const { data, error } = await supabase
        .from('duels')
        .insert({
            challenger_id: user.id,
            opponent_id: opponentId,
            status: 'pending',
            start_date: startDate,
            end_date: endDate
        })
        .select()
        .single();

    if (error) return { error: error.message };

    // Trigger Notification
    await createNotification({
        userId: opponentId,
        type: 'duel_challenge',
        title: 'Duel Issued!',
        content: `${user.user_metadata?.full_name || 'A Rival'} has challenged you to a 7-day duel.`,
        link: '/dashboard'
    });

    revalidatePath('/dashboard/community');
    revalidatePath('/dashboard');
    return { success: true, duel: data };
}

export async function acceptDuel(duelId: string) {
    const supabase = await createClient();
    const { data, error } = await supabase
        .from('duels')
        .update({ status: 'active' })
        .eq('id', duelId)
        .select()
        .single();

    if (error) return { error: error.message };

    // Trigger Notification for the Challenger
    await createNotification({
        userId: data.challenger_id,
        type: 'duel_active',
        title: 'Duel Accepted!',
        content: `Your challenge has been accepted. The 7-day clash begins now!`,
        link: '/dashboard'
    });

    revalidatePath('/dashboard/community');
    revalidatePath('/dashboard');
    return { success: true, duel: data };
}

export async function getMyDuels() {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return [];

    const { data, error } = await supabase
        .from('duels')
        .select(`
            *,
            challenger:challenger_id (username, full_name, avatar_url),
            opponent:opponent_id (username, full_name, avatar_url)
        `)
        .or(`challenger_id.eq.${user.id},opponent_id.eq.${user.id}`)
        .order('created_at', { ascending: false });

    return data || [];
}

export async function getPublicProfile(username: string) {
    const supabase = await createClient();
    const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('username', username)
        .single();

    if (error) return null;
    return data;
}

export async function getCombatStats(userId: string) {
    const supabase = await createClient();

    // Fetch all completed duels for this user
    const { data: duels } = await supabase
        .from('duels')
        .select('*')
        .or(`challenger_id.eq.${userId},opponent_id.eq.${userId}`)
        .eq('status', 'completed');

    const stats = {
        total: duels?.length || 0,
        wins: duels?.filter(d => d.winner_id === userId).length || 0,
        losses: duels?.filter(d => d.winner_id && d.winner_id !== userId).length || 0,
        draws: duels?.filter(d => d.status === 'completed' && !d.winner_id).length || 0
    };

    return stats;
}

import { createClient } from "@/utils/supabase/server";
import Image from "next/image";
import Link from "next/link";
import { Heart, MessageCircle, Share2, MoreHorizontal, Trophy, Dumbbell, UserSearch } from "lucide-react";
import LikeButton from "./LikeButton";
import FollowButton from "./FollowButton";
import DuelButton from "./DuelButton";
import SearchAthletes from "./SearchAthletes";
import { Suspense } from "react";

export const dynamic = 'force-dynamic';

export default async function CommunityPage(props: {
    searchParams: Promise<{ q?: string }>
}) {
    const searchParams = await props.searchParams;
    const query = searchParams.q || "";
    const supabase = await createClient();

    // Get current user to check for follow status
    const { data: { user } } = await supabase.auth.getUser();

    // Fetch follows of current user to highlight rivals
    const { data: myFollows } = await supabase
        .from('follows')
        .select('following_id')
        .eq('follower_id', user?.id || '');

    const followedIds = new Set(myFollows?.map(f => f.following_id) || []);

    let searchResults: any[] = [];
    if (query) {
        const { data: profiles } = await supabase
            .from('profiles')
            .select('*')
            .or(`username.ilike.%${query}%,full_name.ilike.%${query}%`)
            .neq('id', user?.id || '')
            .limit(10);
        searchResults = profiles || [];
    }

    // Fetch all posts with user profile and workout data
    const postsQuery = supabase
        .from('posts')
        .select(`
            *,
            profiles:user_id (id, full_name, avatar_url, username),
            workouts:workout_id (title, total_volume_kg),
            likes:likes(user_id)
        `)
        .order('created_at', { ascending: false });

    if (!query) {
        postsQuery.limit(20);
    } else {
        // If searching, maybe show posts from matched users too? 
        // For now, let's just stick to profile search results or hide posts.
    }

    const { data: posts } = await postsQuery;

    const formatTimeAgo = (date: string) => {
        try {
            const seconds = Math.floor((new Date().getTime() - new Date(date).getTime()) / 1000);
            if (seconds < 60) return `${seconds}s ago`;
            const minutes = Math.floor(seconds / 60);
            if (minutes < 60) return `${minutes}m ago`;
            const hours = Math.floor(minutes / 60);
            if (hours < 24) return `${hours}h ago`;
            return `${Math.floor(hours / 24)}d ago`;
        } catch (e) { return "recently"; }
    }

    return (
        <div className="max-w-2xl mx-auto space-y-8">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-heading font-bold text-white">Global Arena</h1>
                    <p className="text-gray-400 text-sm">See what other athletes are achieving.</p>
                </div>
                <Suspense fallback={<div className="h-10 w-full max-w-md bg-brand-gray animate-pulse rounded-2xl" />}>
                    <SearchAthletes />
                </Suspense>
            </div>

            {query && (
                <div className="space-y-4">
                    <h2 className="text-xl font-heading font-bold text-white flex items-center gap-2">
                        <UserSearch className="w-5 h-5 text-brand-red" />
                        Athletes matching "{query}"
                    </h2>
                    {searchResults.length > 0 ? (
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            {searchResults.map((profile: any) => (
                                <div key={profile.id} className="bg-brand-gray border border-white/5 p-4 rounded-2xl flex items-center justify-between hover:border-white/10 transition-colors">
                                    <Link href={`/dashboard/profile/${profile.username}`} className="flex items-center gap-3 group">
                                        <div className="w-10 h-10 rounded-full bg-gray-800 overflow-hidden relative">
                                            <Image
                                                src={profile.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(profile.full_name || 'User')}&background=random`}
                                                alt={profile.full_name}
                                                fill
                                                className="object-cover group-hover:scale-110 transition-transform"
                                            />
                                        </div>
                                        <div>
                                            <p className="text-sm text-white font-bold group-hover:text-brand-red transition-colors">{profile.full_name}</p>
                                            <p className="text-xs text-gray-500">@{profile.username}</p>
                                        </div>
                                    </Link>
                                    <div className="flex items-center gap-2">
                                        <DuelButton targetId={profile.id} isRival={followedIds.has(profile.id)} />
                                        <FollowButton targetId={profile.id} isFollowingInitial={followedIds.has(profile.id)} />
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="bg-brand-gray/50 border border-dashed border-white/5 rounded-2xl p-8 text-center">
                            <p className="text-gray-500">No athletes found matching your search.</p>
                        </div>
                    )}
                    <div className="h-px bg-white/5 my-8" />
                    <h2 className="text-xl font-heading font-bold text-white">Recent Activity</h2>
                </div>
            )}

            {posts && posts.length > 0 ? (
                posts.map((post: any) => {
                    const hasLiked = post.likes?.some((l: any) => l.user_id === user?.id);
                    const isOwnPost = post.user_id === user?.id;
                    const isFollowing = followedIds.has(post.user_id);

                    return (
                        <div key={post.id} className="bg-brand-gray border border-white/5 rounded-2xl overflow-hidden hover:border-white/10 transition-colors shadow-xl">
                            {/* Post Header */}
                            <div className="p-4 flex items-center justify-between">
                                <Link href={`/dashboard/profile/${post.profiles?.username}`} className="flex items-center gap-3 group">
                                    <div className="w-10 h-10 rounded-full bg-gray-700 overflow-hidden relative border border-white/10">
                                        <Image
                                            src={post.profiles?.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(post.profiles?.full_name || 'User')}&background=random`}
                                            alt={post.profiles?.full_name}
                                            fill
                                            className="object-cover group-hover:scale-110 transition-transform"
                                        />
                                    </div>
                                    <div>
                                        <p className="text-sm text-white font-bold group-hover:text-brand-red transition-colors">
                                            {post.profiles?.full_name}
                                            <span className="text-gray-500 font-normal ml-2">@{post.profiles?.username}</span>
                                        </p>
                                        <p className="text-xs text-gray-500">{formatTimeAgo(post.created_at)}</p>
                                    </div>
                                </Link>
                                <div className="flex items-center gap-2">
                                    {!isOwnPost && (
                                        <div className="flex items-center gap-2">
                                            <DuelButton targetId={post.user_id} isRival={isFollowing} />
                                            <FollowButton targetId={post.user_id} isFollowingInitial={isFollowing} />
                                        </div>
                                    )}
                                    <button className="text-gray-500 hover:text-white">
                                        <MoreHorizontal className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>

                            {/* Post Content */}
                            <div className="px-4 pb-4">
                                <p className="text-gray-200 text-sm mb-4 leading-relaxed">{post.caption}</p>

                                {/* Workout Highlight Box (if available) */}
                                {post.workouts && (
                                    <div className="bg-black/40 border border-brand-red/20 rounded-xl p-4 flex items-center justify-between group hover:border-brand-red/40 transition-colors">
                                        <div className="flex items-center gap-3">
                                            <div className="w-10 h-10 rounded-lg bg-brand-red/10 flex items-center justify-center">
                                                <Dumbbell className="w-5 h-5 text-brand-red" />
                                            </div>
                                            <div>
                                                <p className="text-xs text-brand-red font-bold uppercase tracking-wider">Workout Accomplished</p>
                                                <p className="text-sm text-white font-bold">{post.workouts.title}</p>
                                            </div>
                                        </div>
                                        <div className="text-right">
                                            <div className="flex items-center gap-1 text-yellow-500">
                                                <Trophy className="w-3 h-3" />
                                                <span className="text-[10px] font-bold uppercase">Personal Best</span>
                                            </div>
                                            <p className="text-xs text-gray-500">Vol {post.workouts.total_volume_kg || '0'} Kg</p>
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* Social Actions */}
                            <div className="p-4 border-t border-white/5 bg-black/20">
                                <div className="flex items-center gap-6">
                                    <LikeButton
                                        postId={post.id}
                                        initialLikes={post.likes_count || 0}
                                        hasLikedInitial={!!hasLiked}
                                    />
                                    <button className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors">
                                        <MessageCircle className="w-5 h-5" />
                                        <span className="font-bold text-xs">{post.comments_count || 0}</span>
                                    </button>
                                    <button className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors ml-auto">
                                        <Share2 className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>
                        </div>
                    );
                })
            ) : (
                <div className="text-center py-20 border-2 border-dashed border-white/5 rounded-3xl">
                    <p className="text-gray-500 italic">Static echoes... Be the first to break the silence.</p>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState } from "react";
import { Plus, Search, User } from "lucide-react";
import { addMember, addGuestMember } from "../../management-actions";

export default function MembersManager({ centerId, initialMembers }: any) {
    const [members, setMembers] = useState(initialMembers);
    const [showModal, setShowModal] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [username, setUsername] = useState("");
    const [plan, setPlan] = useState("unlimited");

    async function handleAdd(e: React.FormEvent) {
        e.preventDefault();
        setIsSaving(true);

        let res;
        if (plan === 'guest') {
            const formData = new FormData(e.target as HTMLFormElement);
            const email = formData.get('guest_email') as string;
            res = await addGuestMember(centerId, username, email); // username state holds Full Name here
        } else {
            res = await addMember(centerId, username, plan);
        }

        setIsSaving(false);
        if (res.error) {
            alert(res.error);
        } else {
            setShowModal(false);
            window.location.reload();
        }
    }

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row items-center justify-between gap-4 bg-brand-gray/20 p-4 rounded-2xl border border-white/5 backdrop-blur-sm">
                <div className="relative w-full md:w-auto">
                    <Search className="w-5 h-5 absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" />
                    <input
                        placeholder="Search members..."
                        className="bg-black/60 border border-white/10 rounded-xl pl-10 pr-4 py-3 text-sm text-white focus:border-brand-red outline-none w-full md:w-80 shadow-inner"
                    />
                </div>
                <button
                    onClick={() => setShowModal(true)}
                    className="bg-brand-red text-white py-3 px-6 rounded-xl text-sm font-black uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-red-600 transition-all shadow-lg hover:shadow-red-900/40 w-full md:w-auto"
                >
                    <Plus className="w-5 h-5" /> Add Member
                </button>
            </div>

            <div className="overflow-hidden rounded-2xl border border-white/5 bg-brand-gray/50">
                <table className="w-full text-left text-sm">
                    <thead className="bg-white/5 text-gray-400 font-bold uppercase text-[10px] tracking-wider">
                        <tr>
                            <th className="px-6 py-4">Athlete</th>
                            <th className="px-6 py-4">Membership</th>
                            <th className="px-6 py-4">Status</th>
                            <th className="px-6 py-4">Renewal</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-white/5">
                        {members.map((m: any) => (
                            <tr key={m.id} className="hover:bg-white/5 transition-colors group">
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 rounded-full bg-gray-700 overflow-hidden">
                                            {m.user?.avatar_url ? <img src={m.user.avatar_url} className="w-full h-full object-cover" /> : <User className="p-1.5 w-full h-full text-gray-400" />}
                                        </div>
                                        <div>
                                            <p className="font-bold text-white">{m.user?.full_name || 'Unknown'}</p>
                                            <p className="text-xs text-gray-500">@{m.user?.username}</p>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <span className="bg-white/5 px-2 py-1 rounded text-xs font-bold uppercase">{m.membership_type}</span>
                                </td>
                                <td className="px-6 py-4">
                                    <span className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-full text-[10px] font-black uppercase tracking-wider ${m.is_active ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'}`}>
                                        <span className={`w-1.5 h-1.5 rounded-full ${m.is_active ? 'bg-green-500' : 'bg-red-500'}`} />
                                        {m.is_active ? 'Active' : 'Expired'}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-gray-500 font-mono text-xs">
                                    {new Date(m.renewal_date).toLocaleDateString()}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                {members.length === 0 && (
                    <div className="text-center py-12 text-gray-500 italic">No members found.</div>
                )}
            </div>

            {/* Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                    <div className="bg-brand-gray border border-white/10 rounded-2xl p-6 w-full max-w-sm animate-in fade-in zoom-in duration-200">
                        <h3 className="text-lg font-black text-white italic uppercase mb-4">Add Member</h3>

                        <div className="flex p-1 bg-black/40 rounded-xl mb-4 border border-white/5">
                            <button onClick={() => setPlan('unlimited')} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all ${plan !== 'guest' ? 'bg-brand-red text-white' : 'text-gray-500 hover:text-white'}`}>Rival User</button>
                            <button onClick={() => setPlan('guest')} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all ${plan === 'guest' ? 'bg-white text-black' : 'text-gray-500 hover:text-white'}`}>Guest / Trial</button>
                        </div>

                        <form onSubmit={handleAdd} className="space-y-4">
                            {plan !== 'guest' ? (
                                <>
                                    <div>
                                        <label className="block text-[10px] font-black uppercase tracking-widest text-gray-500 mb-1 ml-1">Username</label>
                                        <input required value={username} onChange={e => setUsername(e.target.value)} className="w-full bg-black/40 border border-white/10 rounded-xl p-3 text-white outline-none focus:border-brand-red text-sm" placeholder="Exact username" />
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-black uppercase tracking-widest text-gray-500 mb-1 ml-1">Plan</label>
                                        <select value={plan === 'guest' ? 'unlimited' : plan} onChange={e => setPlan(e.target.value)} className="w-full bg-black/40 border border-white/10 rounded-xl p-3 text-white outline-none focus:border-brand-red text-sm appearance-none">
                                            <option value="unlimited">Unlimited Access</option>
                                            <option value="3x_week">3x Per Week</option>
                                            <option value="punch_card">10 Class Pack</option>
                                        </select>
                                    </div>
                                </>
                            ) : (
                                <>
                                    <div>
                                        <label className="block text-[10px] font-black uppercase tracking-widest text-gray-500 mb-1 ml-1">Full Name</label>
                                        <input required value={username} onChange={e => setUsername(e.target.value)} className="w-full bg-black/40 border border-white/10 rounded-xl p-3 text-white outline-none focus:border-white text-sm" placeholder="John Doe" />
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-black uppercase tracking-widest text-gray-500 mb-1 ml-1">Email (Optional)</label>
                                        <input type="email" name="guest_email" className="w-full bg-black/40 border border-white/10 rounded-xl p-3 text-white outline-none focus:border-white text-sm" placeholder="john@example.com" />
                                    </div>
                                    <div className="bg-blue-500/10 border border-blue-500/20 p-3 rounded-xl">
                                        <p className="text-xs text-blue-400">Guest will be added with a 24h Trial Pass.</p>
                                    </div>
                                </>
                            )}

                            <div className="flex gap-2 mt-6">
                                <button type="button" onClick={() => setShowModal(false)} className="flex-1 bg-transparent border border-white/10 text-white py-3 rounded-xl text-xs font-black uppercase hover:bg-white/5">Cancel</button>
                                <button type="submit" disabled={isSaving} className="flex-1 bg-white text-black py-3 rounded-xl text-xs font-black uppercase hover:bg-brand-red hover:text-white disabled:opacity-50">{isSaving ? 'Adding...' : 'Add Member'}</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    )
}

