function QuickAction({ href, icon: Icon, label, disabled }: any) {
    if (disabled) {
        return (
            <div className="bg-black border border-white/10 rounded-2xl p-6 flex flex-col items-center justify-center gap-3 opacity-50 cursor-not-allowed">
                <Icon className="w-6 h-6 text-gray-500" />
