        )
    }
    return (
        <Link
            href={href}
            className="bg-black border border-white/10 rounded-2xl p-6 flex flex-col items-center justify-center gap-3 hover:bg-white/5 hover:border-white/20 hover:-translate-y-1 transition-all group"
        >
            <Icon className="w-6 h-6 text-brand-red group-hover:scale-110 transition-transform" />
            <span className="font-bold text-white text-sm">{label}</span>
        </Link>
    )
}

"use client";

import { useState } from "react";
import { Plus, Trash2, Calendar as CalIcon, Clock, Users } from "lucide-react";
import { createClass, deleteClass } from "../../management-actions";

export default function ScheduleManager({ centerId, initialClasses, coaches }: any) {
    const [classes, setClasses] = useState(initialClasses);
    const [showModal, setShowModal] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    // Form State
    const [formData, setFormData] = useState({
        name: "",
        coach_id: coaches[0]?.user_id || "",
        date: new Date().toISOString().split('T')[0],
        time: "17:00",
        duration: "60",
        capacity: "20",
        type: "crossfit",
        difficulty: "intermediate"
    });

    async function handleCreate(e: React.FormEvent) {
        e.preventDefault();
        setIsSaving(true);

        const scheduled_time = new Date(`${formData.date}T${formData.time}:00`).toISOString();

        const res = await createClass(centerId, { ...formData, scheduled_time });

        setIsSaving(false);
        if (res.error) {
            alert(res.error);
        } else {
            setShowModal(false);
            window.location.reload();
        }
    }

    async function handleDelete(id: string) {
        if (!confirm("Delete this class?")) return;
        const res = await deleteClass(centerId, id);
        if (res.success) {
            setClasses(classes.filter((c: any) => c.id !== id));
        }
    }

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-xl font-bold text-white">Class Schedule</h2>
                <button
                    onClick={() => setShowModal(true)}
                    className="bg-brand-red text-white px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest flex items-center gap-2 hover:bg-red-600 transition-all"
                >
                    <Plus className="w-4 h-4" /> Add Class
                </button>
            </div>

            <div className="space-y-4">
                {classes.map((cls: any) => (
                    <div key={cls.id} className="bg-brand-gray border border-white/5 p-4 rounded-xl flex items-center justify-between group hover:border-brand-red/30 transition-all">
                        <div className="flex items-center gap-4">
                            <div className="bg-black/40 p-3 rounded-lg text-center min-w-[60px]">
                                <span className="block text-brand-red font-black text-sm">{new Date(cls.scheduled_time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                <span className="block text-[10px] text-gray-500 font-bold uppercase">{cls.duration_minutes}m</span>
                            </div>
                            <div>
                                <h3 className="font-heading font-black text-white italic text-lg">{cls.name}</h3>
                                <div className="flex items-center gap-3 text-xs text-gray-500">
                                    <span className="flex items-center gap-1"><Users className="w-3 h-3" /> {cls.enrolled_count}/{cls.max_capacity}</span>
                                    <span>• Coach: {cls.coach?.full_name || 'Staff'}</span>
                                    <span className="capitalize px-2 py-0.5 bg-white/5 rounded text-[10px]">{cls.class_type}</span>
                                </div>
                            </div>
                        </div>
                        <div className="flex items-center gap-2">
                            <a href={`/dashboard/gyms/${centerId}/schedule/${cls.id}`} className="px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-xs font-bold uppercase hover:bg-white hover:text-black transition-all">
                                Manage
                            </a>
                            <button onClick={() => handleDelete(cls.id)} className="p-2 text-gray-600 hover:text-red-500 transition-all">
                                <Trash2 className="w-4 h-4" />
                            </button>
                        </div>
                    </div>
                ))}

                {classes.length === 0 && (
                    <div className="text-center py-10 border-2 border-dashed border-white/5 rounded-xl">
                        <p className="text-gray-500">No classes scheduled.</p>
                    </div>
                )}
            </div>

            {/* Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                    <div className="bg-brand-gray border border-white/10 rounded-2xl p-6 w-full max-w-md animate-in fade-in zoom-in duration-200">
                        <h3 className="text-lg font-black text-white italic uppercase mb-4">Schedule Class</h3>
                        <form onSubmit={handleCreate} className="space-y-4">
                            <div>
                                <label className="label">Class Name</label>
                                <input required value={formData.name} onChange={e => setFormData({ ...formData, name: e.target.value })} className="input" placeholder="WOD, Yoga Flow..." />
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="label">Date</label>
                                    <input type="date" required value={formData.date} onChange={e => setFormData({ ...formData, date: e.target.value })} className="input" />
                                </div>
                                <div>
                                    <label className="label">Time</label>
                                    <input type="time" required value={formData.time} onChange={e => setFormData({ ...formData, time: e.target.value })} className="input" />
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="label">Coach</label>
                                    <select value={formData.coach_id} onChange={e => setFormData({ ...formData, coach_id: e.target.value })} className="input appearance-none">
                                        {coaches.map((c: any) => (
                                            <option key={c.id} value={c.user_id}>{c.user?.full_name || c.user?.username}</option>
                                        ))}
                                    </select>
                                </div>
                                <div>
                                    <label className="label">Capacity</label>
                                    <input type="number" required value={formData.capacity} onChange={e => setFormData({ ...formData, capacity: e.target.value })} className="input" />
                                </div>
                            </div>

                            <div className="flex gap-2 mt-6">
                                <button type="button" onClick={() => setShowModal(false)} className="btn-secondary flex-1">Cancel</button>
                                <button type="submit" disabled={isSaving} className="btn-primary flex-1">{isSaving ? 'Scheduling...' : 'Create Class'}</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            <style jsx>{`
                .label { font-size: 10px; font-weight: 900; text-transform: uppercase; letter-spacing: 0.1em; color: #6b7280; margin-left: 4px; display: block; margin-bottom: 4px; }
                .input { width: 100%; background: rgba(0,0,0,0.4); border: 1px solid rgba(255,255,255,0.1); border-radius: 0.75rem; padding: 0.75rem; color: white; outline: none; font-size: 0.875rem; }
                .input:focus { border-color: #dc2626; }
                .btn-primary { background: white; color: black; padding: 0.75rem; border-radius: 0.75rem; font-size: 0.75rem; font-weight: 900; text-transform: uppercase; letter-spacing: 0.05em; transition: all; }
                .btn-primary:hover { background: #dc2626; color: white; }
                .btn-secondary { background: transparent; border: 1px solid rgba(255,255,255,0.1); color: white; padding: 0.75rem; border-radius: 0.75rem; font-size: 0.75rem; font-weight: 900; text-transform: uppercase; letter-spacing: 0.05em; }
                .btn-secondary:hover { background: rgba(255,255,255,0.05); }
            `}</style>
        </div>
    )
}

"use client";

import { useState } from "react";
import { Check, X, Loader2 } from "lucide-react";
import { markAttendance } from "../../../management-actions";

export default function AttendanceToggle({ enrollmentId, initialAttended, path }: any) {
    const [status, setStatus] = useState<boolean | null>(initialAttended);
    const [loading, setLoading] = useState(false);

    async function handleToggle(value: boolean) {
        if (loading) return;
        setLoading(true);
        // Optimistic UI
        setStatus(value);

        const res = await markAttendance(enrollmentId, value, path);
        if (res.error) {
            alert("Error updating attendance");
            setStatus(initialAttended); // Revert
        }
        setLoading(false);
    }

    return (
        <div className="flex bg-black rounded-lg p-1 border border-white/10">
            <button
                onClick={() => handleToggle(true)}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-[10px] font-black uppercase transition-all ${status === true ? 'bg-green-500 text-black shadow-lg' : 'text-gray-600 hover:text-green-500'}`}
                title="Mark Present"
            >
                {loading && status === true ? <Loader2 className="w-3 h-3 animate-spin" /> : <Check className="w-3 h-3" />}
                Present
            </button>
            <button
                onClick={() => handleToggle(false)}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-[10px] font-black uppercase transition-all ${status === false ? 'bg-red-500 text-white shadow-lg' : 'text-gray-600 hover:text-red-500'}`}
                title="Mark Absent"
            >
                {loading && status === false ? <Loader2 className="w-3 h-3 animate-spin" /> : <X className="w-3 h-3" />}
                Absent
            </button>
        </div>
    )
}

"use client";

import { useState } from "react";
import { Plus, Shield, Trash2, User, Mail, MoreHorizontal } from "lucide-react";
import { inviteTeamMember, removeTeamMember } from "../../actions";
import Image from "next/image";

interface TeamMember {
    id: string;
    role: string;
    created_at: string;
    user: {
        id: string;
        full_name: string;
        username: string;
        avatar_url: string;
    };
}

export default function TeamManagement({ centerId, initialTeam }: { centerId: string, initialTeam: TeamMember[] }) {
    const [team, setTeam] = useState<TeamMember[]>(initialTeam);
    const [isInviting, setIsInviting] = useState(false);
    const [loading, setLoading] = useState(false);

    // Modal State
    const [showModal, setShowModal] = useState(false);
    const [inviteUsername, setInviteUsername] = useState("");
    const [inviteRole, setInviteRole] = useState("coach");

    async function handleInvite(e: React.FormEvent) {
        e.preventDefault();
        setLoading(true);

        const res = await inviteTeamMember(centerId, inviteUsername, inviteRole);

        setLoading(false);
        if (res.error) {
            alert(res.error);
        } else {
            alert("Member added successfully!");
            setShowModal(false);
            setInviteUsername("");
            // In a real app we'd re-fetch or use router.refresh(). 
            // For now, let's force a reload or trust revalidatePath if this was a server component children.
            // Since we passed initialTeam, we should probably use router.refresh() 
            // but let's just reload the window for MVP simplicity or assume Next.js handles it if we call useRouter.
            window.location.reload();
        }
    }

    async function handleRemove(userId: string) {
        if (!confirm("Are you sure you want to remove this member?")) return;

        const res = await removeTeamMember(centerId, userId);
        if (res.error) {
            alert(res.error);
        } else {
            setTeam(prev => prev.filter(m => m.user.id !== userId));
        }
    }

    return (
        <div className="space-y-8">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-xl font-bold text-white">Team Members</h2>
                    <p className="text-sm text-gray-500">Manage access and roles for your facility.</p>
                </div>
                <button
                    onClick={() => setShowModal(true)}
                    className="bg-white text-black px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest flex items-center gap-2 hover:bg-brand-red hover:text-white transition-all"
                >
                    <Plus className="w-4 h-4" /> Add Member
                </button>
            </div>

            {/* Team Grid */}
            <div className="grid gap-4">
                {team.map((member) => (
                    <div key={member.id} className="bg-brand-gray border border-white/5 p-4 rounded-xl flex items-center justify-between group hover:border-white/10 transition-all">
                        <div className="flex items-center gap-4">
                            <div className="w-12 h-12 rounded-full border-2 border-white/5 overflow-hidden bg-gray-800">
                                {member.user.avatar_url ? (
                                    <img src={member.user.avatar_url} alt={member.user.username} className="w-full h-full object-cover" />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center text-gray-500">
                                        <User className="w-6 h-6" />
                                    </div>
                                )}
                            </div>
                            <div>
                                <h3 className="font-bold text-white text-sm">{member.user.full_name || member.user.username}</h3>
                                <div className="flex items-center gap-2 text-xs text-gray-500">
                                    <span className="bg-white/5 px-2 py-0.5 rounded text-[10px] font-black uppercase tracking-wider text-brand-red">
                                        {member.role.replace('_', ' ')}
                                    </span>
                                    <span>• @{member.user.username}</span>
                                </div>
                            </div>
                        </div>

                        <div className="flex items-center gap-2">
                            {member.role !== 'owner' && (
                                <button
                                    onClick={() => handleRemove(member.user.id)}
                                    className="p-2 text-gray-600 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                                    title="Remove User"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            )}
                        </div>
                    </div>
                ))}

                {team.length === 0 && (
                    <div className="text-center py-10">
                        <p className="text-gray-500 italic">No team members found.</p>
                    </div>
                )}
            </div>

            {/* Invite Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                    <div className="bg-brand-gray border border-white/10 rounded-2xl p-6 w-full max-w-sm animate-in fade-in zoom-in duration-200">
                        <h3 className="text-lg font-black text-white italic uppercase mb-4">Add Team Member</h3>
                        <form onSubmit={handleInvite} className="space-y-4">
                            <div>
                                <label className="text-[10px] font-black uppercase tracking-widest text-gray-500 ml-1">Username</label>
                                <div className="relative">
                                    <User className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" />
                                    <input
                                        type="text"
                                        required
                                        value={inviteUsername}
                                        onChange={e => setInviteUsername(e.target.value)}
                                        placeholder="Username (exact match)"
                                        className="w-full bg-black/40 border border-white/10 rounded-xl p-3 pl-10 text-white focus:border-brand-red outline-none text-sm"
                                    />
                                </div>
                                <p className="text-[10px] text-gray-600 mt-1 ml-1">* Must match an existing Rival username exactly.</p>
                            </div>

                            <div>
                                <label className="text-[10px] font-black uppercase tracking-widest text-gray-500 ml-1">Role</label>
                                <div className="grid grid-cols-2 gap-2">
                                    <button
                                        type="button"
                                        onClick={() => setInviteRole('head_coach')}
                                        className={`p-3 rounded-xl border text-xs font-bold uppercase transition-all ${inviteRole === 'head_coach' ? 'bg-brand-red text-white border-brand-red' : 'bg-black/40 border-white/10 text-gray-500 hover:text-white'}`}
                                    >
                                        Head Coach
                                    </button>
                                    <button
                                        type="button"
                                        onClick={() => setInviteRole('coach')}
                                        className={`p-3 rounded-xl border text-xs font-bold uppercase transition-all ${inviteRole === 'coach' ? 'bg-brand-red text-white border-brand-red' : 'bg-black/40 border-white/10 text-gray-500 hover:text-white'}`}
                                    >
                                        Coach
                                    </button>
                                </div>
                            </div>

                            <div className="flex gap-2 mt-6">
                                <button type="button" onClick={() => setShowModal(false)} className="flex-1 bg-transparent border border-white/10 text-white py-3 rounded-xl text-xs font-black uppercase hover:bg-white/5">Cancel</button>
                                <button type="submit" disabled={loading} className="flex-1 bg-white text-black py-3 rounded-xl text-xs font-black uppercase hover:bg-brand-red hover:text-white transition-colors disabled:opacity-50">
                                    {loading ? 'Adding...' : 'Add Member'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

import { getCenterTeam } from "../../actions";
import TeamManagement from "./TeamManagement";
import { Users } from "lucide-react";

export default async function TeamPage({ params }: { params: { id: string } }) {
    const { id } = await params;

    // Fetch initial team data on the server
    const rawTeam = await getCenterTeam(id);

    // Normalize data (Supabase sometimes returns relations as arrays)
    const team = (rawTeam || []).map((member: any) => ({
        ...member,
        user: Array.isArray(member.user) ? member.user[0] : member.user
    }));

    return (
        <div className="p-8 space-y-8 animate-fade-in">
            <div className="flex items-start gap-4 mb-8 border-b border-white/5 pb-8">
                <div className="p-3 bg-brand-red/10 rounded-2xl border border-brand-red/20 text-brand-red">
                    <Users className="w-8 h-8" />
                </div>
                <div>
                    <h1 className="text-3xl font-heading font-black text-white italic uppercase">Access Control</h1>
