                </div>
            </div>

            <TeamManagement centerId={id} initialTeam={team} />
        </div>
    );
}

"use client";

import { useState } from "react";
import { Plus, Trash2, FileText, Image as ImageIcon } from "lucide-react";
import { createWod, deletePost } from "../../management-actions";

export default function WodManager({ centerId, initialPosts }: any) {
    const [posts, setPosts] = useState(initialPosts);
    const [content, setContent] = useState("");
    const [isPosting, setIsPosting] = useState(false);

    async function handlePost(e: React.FormEvent) {
        e.preventDefault();
        if (!content.trim()) return;
        setIsPosting(true);

        const res = await createWod(centerId, content);
        setIsPosting(false);

        if (res.error) {
            alert(res.error);
        } else {
            setContent("");
            window.location.reload();
        }
    }

    async function handleDelete(id: string) {
        if (!confirm("Remove this post?")) return;
        const res = await deletePost(centerId, id);
        if (res.success) {
            setPosts(posts.filter((p: any) => p.id !== id));
        }
    }

    return (
        <div className="grid lg:grid-cols-3 gap-8">
            {/* Create Post */}
            <div className="lg:col-span-1">
                <div className="bg-brand-gray border border-white/5 rounded-2xl p-6 sticky top-8">
                    <h3 className="text-lg font-black text-white italic uppercase mb-4">Publish WOD</h3>
                    <form onSubmit={handlePost} className="space-y-4">
                        <textarea
                            value={content}
                            onChange={(e) => setContent(e.target.value)}
                            placeholder="Write today's workout details..."
                            className="w-full h-48 bg-black/40 border border-white/10 rounded-xl p-4 text-white outline-none focus:border-brand-red text-sm resize-none"
                            required
                        />
                        <div className="flex items-center justify-between">
                            <button type="button" className="p-2 text-gray-500 hover:text-white transition-colors">
                                <ImageIcon className="w-5 h-5" />
                            </button>
                            <button
                                type="submit"
                                disabled={isPosting}
                                className="bg-brand-red text-white px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-red-600 transition-all disabled:opacity-50"
                            >
                                {isPosting ? 'Posting...' : 'Publish'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>

            {/* Feed */}
            <div className="lg:col-span-2 space-y-6">
                {posts.map((post: any) => (
                    <div key={post.id} className="bg-brand-gray border border-white/5 rounded-2xl p-6 group">
                        <div className="flex items-start justify-between mb-4">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-full bg-gray-700 overflow-hidden">
                                    {post.author?.avatar_url ? <img src={post.author.avatar_url} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-gray-800" />}
                                </div>
                                <div>
                                    <p className="text-white font-bold text-sm">{post.author?.full_name || 'Coach'}</p>
                                    <p className="text-xs text-gray-500">{new Date(post.created_at).toLocaleDateString()} • {new Date(post.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                                </div>
                            </div>
                            <button onClick={() => handleDelete(post.id)} className="text-gray-600 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                                <Trash2 className="w-4 h-4" />
                            </button>
                        </div>

