'use server'

import { createClient } from "@/utils/supabase/server";
import { revalidatePath } from "next/cache";

export type Role = 'owner' | 'head_coach' | 'coach' | 'athlete';

export async function getUserOrganizations() {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return [];

    // 1. Get organizations owned by user
    const { data: ownedOrgs, error: ownedError } = await supabase
        .from('organizations')
        .select('*')
        .eq('owner_id', user.id);

    if (ownedError) {
        console.error("Error fetching owned orgs:", ownedError);
    }

    // 2. Get organizations where user is a team member
    const { data: memberOrgs, error: memberError } = await supabase
        .from('center_roles')
        .select('organization_id, role, organizations(*)')
        .eq('user_id', user.id);

    if (memberError) {
        console.error("Error fetching member orgs:", memberError);
    }

    // Combine and deduplicate
    const allOrgs = [...(ownedOrgs || [])];

    if (memberOrgs) {
        memberOrgs.forEach((mo: any) => {
            if (!allOrgs.find(o => o.id === mo.organization_id)) {
                // Attach the role context to the organization object for easier UI usage
                const orgWithRole = { ...mo.organizations, user_role: mo.role };
                allOrgs.push(orgWithRole);
            }
        });
    }

    // Assign 'owner' role to owned orgs if not present
    return allOrgs.map(org => ({
        ...org,
        user_role: org.owner_id === user.id ? 'owner' : (org.user_role || 'member')
    }));
}

export async function createOrganization(formData: FormData) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return { error: "Not authenticated" };

    const name = formData.get('name') as string;
    const city = formData.get('city') as string;
    const country = formData.get('country') as string;
    const type = formData.get('type') as string;

    if (!name || !city || !country) return { error: "Missing fields" };

    const { data, error } = await supabase
        .from('organizations')
        .insert({
            name,
            city,
            country,
            center_type: type,
            owner_id: user.id,
            email: user.email, // Default to owner email initially
            plan: 'free',
            member_count: 1 // The owner
        })
        .select()
        .single();

    if (error) return { error: error.message };

    // Add owner as a 'head_coach' role implicitly effectively or explicitly?
    // Owners usually have separate permissions, but adding a role helps with queries.
    // Let's add them as head_coach as well so they show up in lists if needed, 
    // or rely on owner_id check. For now, let's keep it clean: Owner is Owner.

    revalidatePath('/dashboard/gyms');
    return { success: true, org: data };
}

export async function getCenterTeam(centerId: string) {
    const supabase = await createClient();

    // Get roles
    const { data: roles, error } = await supabase
        .from('center_roles')
        .select(`
            id,
            role,
            created_at,
            user:user_id (id, full_name, username, avatar_url)
        `)
        .eq('organization_id', centerId);

    if (error) {
        console.error("Error fetching team:", error);
        return [];
    }

    return roles || [];
}

export async function inviteTeamMember(centerId: string, email: string, role: string) {
    const supabase = await createClient();

    // 1. Check if user exists
    // Note: In a real app we might use an edge function to look up by email to avoid exposing emails/privacy issues,
    // or send an invite email if they don't exist.
    // For MVP, we assume user might be in our profiles table (or auth).
    // Accessing auth.users is restricted. We'll search public.profiles if email is there? 
    // Usually profiles don't publish email for privacy.
    // WORKAROUND MVP: Search by username or exact email match if we stored email in profiles (which we do in Supabase usually if synced).
    // Let's assume we can search profiles by email (requires RLS to allow it or `security definer` function).
    // Since we don't have that ready, let's search by username for now? 
    // User requested "email" typically. 
    // Let's assume there is a `get_user_by_email` RPC or we blindly insert if we can't check.

    // BETTER MVP: The user inputs a Username. It's safer.
    // But the user typically inputs email.
    // Let's look at the database schema for profiles again. It has no email column visible in previous `page.tsx` snippets.
    // Wait, the `getCenterTeam` uses `user:user_id (email)`... does profile have email?
    // `supabase_b2b.sql` references profiles(id).

    // Let's try to fetch user by email from profiles if column exists.
    // If not, we fall back to username.

    // Assuming we can't easily query by email due to privacy/schema:
    // We will ask for EXACT USERNAME for this internal MVP tool.

    // Wait, creating center roles requires user_id.

    // Attempt to finding user by username
    const { data: profile, error: profileError } = await supabase
        .from('profiles')
        .select('id')
        .eq('username', email) // Using the input as username
        .single();

    if (!profile) {
        // Try searching by exact match on a hidden email column? Unlikely to work with RLS.
        return { error: "User not found. Please use their exact Username." };
    }

    // 2. Add Role
    const { error: insertError } = await supabase
        .from('center_roles')
        .insert({
            organization_id: centerId,
            user_id: profile.id,
            role: role
        });

    if (insertError) {
        if (insertError.code === '23505') { // Unique violation
            return { error: "User is already in the team." };
        }
        return { error: insertError.message };
    }

    revalidatePath(`/dashboard/gyms/${centerId}/team`);
    return { success: true };
}

export async function removeTeamMember(centerId: string, userId: string) {
    const supabase = await createClient();

