"use client";

import { useEffect, useState, useRef } from "react";
import { getUserProfile } from "../training/actions";

import { createClient } from "@/utils/supabase/client";
import { User, Camera, Save, Loader2, Mail, Hash, MapPin, Trophy, Dumbbell, Swords, Award, ExternalLink, TrendingUp, Building2 } from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { getCombatStats } from "../community/duel-actions";

export default function ProfilePage() {
    const [profile, setProfile] = useState<any>(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [uploading, setUploading] = useState(false);
    const [formData, setFormData] = useState({
        full_name: "",
        username: "",
        bio: "",
        main_sport: "",
        gym_home: "",
    });
    const [combatStats, setCombatStats] = useState<any>({ wins: 0, losses: 0, draws: 0, total: 0 });
    const [workouts, setWorkouts] = useState<any[]>([]);

    const fileInputRef = useRef<HTMLInputElement>(null);
    const supabase = createClient();
    const router = useRouter();

    useEffect(() => {
        async function loadProfile() {
            const data = await getUserProfile();
            if (data) {
                setProfile(data);
                setFormData({
                    full_name: data.full_name || "",
                    username: data.username || "",
                    bio: data.bio || "",
                    main_sport: data.main_sport || "General",
                    gym_home: data.gym_home || "",
                });

                // Load Combat Stats
                const stats = await getCombatStats(data.id);
                setCombatStats(stats);

                // Load Workouts
                const { data: userWorkouts, error: workoutError } = await supabase
                    .from('workouts')
                    .select('*')
                    .eq('user_id', data.id)
                    .order('start_time', { ascending: false });

                if (workoutError) console.error("Error fetching workouts:", workoutError);
                setWorkouts(userWorkouts || []);
            }
            setLoading(false);
        }
        loadProfile();
    }, []);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        setFormData(prev => ({ ...prev, [e.target.name]: e.target.value }));
    };

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) return;

            const { error } = await supabase
                .from('profiles')
                .update({
                    full_name: formData.full_name,
                    username: formData.username,
                    bio: formData.bio,
                    main_sport: formData.main_sport,
                    gym_home: formData.gym_home,
                    updated_at: new Date().toISOString(),
                })
                .eq('id', user.id);

            if (error) throw error;
            router.refresh();
            // Show some success toast/feedback
        } catch (error) {
            console.error("Error updating profile:", error);
            alert("Error updating profile. Check console.");
        } finally {
            setSaving(false);
        }
    };

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
