        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
            <path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6" />
            <path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18" />
            <path d="M4 22h16" />
            <path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22" />
            <path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22" />
            <path d="M18 2H6v7a6 6 0 0 0 12 0V2Z" />
        </svg>
    )
}

"use client";

import Link from "next/link";
import { ArrowLeft, CheckCircle, Clock, Save, Loader2, List, Plus, X } from "lucide-react";
import { useState, useEffect } from "react";
import { saveWorkout, getExercises } from "../actions";
import { useRouter } from "next/navigation";

export default function SessionPage() {
    const router = useRouter();
    const [isSaving, setIsSaving] = useState(false);
    const [startTime] = useState(new Date());
    const [workoutTitle] = useState("Lower Body Destruction");
    const [showTimer, setShowTimer] = useState(false);
    const [showAddModal, setShowAddModal] = useState(false);
    const [catalog, setCatalog] = useState<any[]>([]);

    // Initial State: List of exercises, each with a list of sets
    const [exercises, setExercises] = useState([
        {
            id: 'initial-1',
            name: "Back Squat",
            target: "4 sets x 6-8 reps",
            prev: "135kg x 8",
            sets: [
                { order: 1, weight: 140, reps: 6, completed: false },
                { order: 2, weight: 140, reps: 6, completed: false },
                { order: 3, weight: 140, reps: 6, completed: false },
                { order: 4, weight: 140, reps: 6, completed: false },
            ]
        }
    ]);

    useEffect(() => {
        const fetchCatalog = async () => {
            const data = await getExercises();
            setCatalog(data);
        };
        fetchCatalog();
    }, []);

    const addExerciseToWorkout = (exerciseTemplate: any) => {
        const newEx = {
            id: Math.random().toString(36).substr(2, 9),
            name: exerciseTemplate.name,
            target: "3 sets x 10 reps",
            prev: "0kg x 0",
            sets: [
                { order: 1, weight: 0, reps: 0, completed: false }
            ]
        };
        setExercises([...exercises, newEx]);
        setShowAddModal(false);
    };

    const addSet = (exIndex: number) => {
        const newExercises = [...exercises];
        const ex = newExercises[exIndex];
        const lastSet = ex.sets[ex.sets.length - 1];
        ex.sets.push({
            order: ex.sets.length + 1,
            weight: lastSet ? lastSet.weight : 0,
            reps: lastSet ? lastSet.reps : 0,
            completed: false
        });
        setExercises(newExercises);
    };

    const updateSet = (exerciseIndex: number, setIndex: number, field: string, value: any) => {
        const newExercises = [...exercises];
        const set = newExercises[exerciseIndex].sets[setIndex];
        // @ts-ignore
        set[field] = value;
        setExercises(newExercises);
    };

    const toggleSetComplete = (exerciseIndex: number, setIndex: number) => {
        const current = exercises[exerciseIndex].sets[setIndex].completed;
        updateSet(exerciseIndex, setIndex, "completed", !current);
    };

    const handleFinish = async () => {
        try {
            setIsSaving(true);
            const payload = {
                title: workoutTitle,
                startTime: startTime.toISOString(),
                duration: Math.floor((new Date().getTime() - startTime.getTime()) / 1000),
                exercises: exercises,
                rpe: 8
            };

            const result = await saveWorkout(payload);
            if (result && result.error) {
                alert("Error saving workout: " + result.error);
                setIsSaving(false);
            } else if (result && result.success) {
                router.push('/dashboard');
                router.refresh();
            }
        } catch (e: any) {
            if (e.message !== 'NEXT_REDIRECT') {
                alert("Unexpected error: " + (e.message || JSON.stringify(e)));
                setIsSaving(false);
            }
        }
    };

    return (
        <div className="max-w-3xl mx-auto pb-20">
            {/* Top Bar */}
            <div className="flex items-center justify-between mb-8 sticky top-0 bg-black/95 py-4 z-20 border-b border-white/5 backdrop-blur-md">
                <Link href="/dashboard/training" className="text-gray-400 hover:text-white transition-colors">
                    <ArrowLeft className="w-6 h-6" />
                </Link>
                <div className="flex flex-col items-center">
                    <span className="text-white font-heading font-bold">{workoutTitle}</span>
                    <div className="flex items-center gap-1 text-brand-red text-xs font-mono">
                        <Clock className="w-3 h-3" /> Live
                    </div>
                </div>
                <button
                    onClick={handleFinish}
                    disabled={isSaving}
                    className="bg-brand-red hover:bg-brand-accent text-white font-bold text-sm px-4 py-2 rounded-full flex items-center gap-2 transition-all disabled:opacity-50"
                >
                    {isSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                    Finish
                </button>
            </div>

            {/* Exercises List */}
            <div className="space-y-8">
                {exercises.map((exercise, exIndex) => (
                    <div key={exercise.id} className="bg-brand-gray/50 rounded-3xl border border-white/5 overflow-hidden backdrop-blur-sm shadow-xl">
                        <div className="p-6 border-b border-white/5 flex justify-between items-center bg-white/5">
                            <div>
                                <h3 className="font-heading font-black text-xl text-white tracking-tight uppercase italic">{exercise.name}</h3>
                                <div className="flex items-center gap-2 mt-1">
                                    <span className="text-[10px] text-brand-red font-bold uppercase tracking-widest bg-brand-red/10 px-2 py-0.5 rounded border border-brand-red/20">{exercise.target}</span>
                                    <span className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Prev: {exercise.prev}</span>
                                </div>
                            </div>
                            <button className="text-gray-500 hover:text-white transition-colors">
                                <List className="w-5 h-5" />
                            </button>
                        </div>

                        <div className="p-4">
                            <div className="grid grid-cols-12 gap-2 mb-4 px-4 text-[10px] font-black text-gray-600 uppercase tracking-widest">
                                <div className="col-span-1 text-center">Set</div>
                                <div className="col-span-3 text-center">Previous</div>
                                <div className="col-span-3 text-center">Weight (kg)</div>
                                <div className="col-span-3 text-center">Reps</div>
                                <div className="col-span-2 text-center">Status</div>
                            </div>

                            <div className="space-y-2">
                                {exercise.sets.map((set, setIndex) => (
                                    <div key={setIndex} className={`grid grid-cols-12 gap-2 p-2 rounded-2xl items-center transition-all ${set.completed ? 'bg-green-500/5 border border-green-500/10 opacity-60' : 'bg-black/20 border border-white/5'}`}>
                                        <div className="col-span-1 text-center font-black text-white italic">{set.order}</div>
                                        <div className="col-span-3 text-center text-gray-500 text-sm font-bold">
                                            {exercise.prev.split(' ')[0]}
                                        </div>
                                        <div className="col-span-3 px-1">
                                            <input
                                                type="number"
                                                className="w-full bg-black/40 border border-white/5 rounded-xl p-3 text-white text-center font-black text-lg focus:border-brand-red focus:outline-none focus:ring-2 focus:ring-brand-red/20 transition-all"
                                                value={set.weight}
                                                onChange={(e) => updateSet(exIndex, setIndex, 'weight', e.target.value)}
                                            />
                                        </div>
                                        <div className="col-span-3 px-1">
                                            <input
                                                type="number"
                                                className="w-full bg-black/40 border border-white/5 rounded-xl p-3 text-white text-center font-black text-lg focus:border-brand-red focus:outline-none focus:ring-2 focus:ring-brand-red/20 transition-all"
                                                value={set.reps}
                                                onChange={(e) => updateSet(exIndex, setIndex, 'reps', e.target.value)}
                                            />
                                        </div>
                                        <div className="col-span-2 flex justify-center">
                                            <button
                                                onClick={() => {
                                                    toggleSetComplete(exIndex, setIndex);
                                                    if (!set.completed) setShowTimer(true);
                                                }}
                                                className={`w-12 h-12 rounded-xl flex items-center justify-center transition-all ${set.completed
                                                    ? 'bg-green-500 text-white shadow-[0_0_15px_rgba(34,197,94,0.4)]'
                                                    : 'bg-white/5 text-gray-500 border border-white/5 hover:border-green-500/50 hover:text-green-500'
                                                    }`}
                                            >
                                                <CheckCircle className={`w-6 h-6 ${set.completed ? 'fill-current' : ''}`} />
                                            </button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>

                        <div className="p-4 bg-black/20 border-t border-white/5">
                            <button
                                onClick={() => addSet(exIndex)}
                                className="w-full py-3 rounded-xl border border-dashed border-white/10 text-gray-500 text-xs font-bold uppercase tracking-widest hover:border-white/30 hover:text-gray-300 transition-all">
                                + Add Set
                            </button>
                        </div>
                    </div>
                ))}
            </div>

            {/* Rest Timer Overlay */}
            {showTimer && <RestTimer onClose={() => setShowTimer(false)} />}

            <div className="mt-12 text-center pb-20">
                <button
                    onClick={() => setShowAddModal(true)}
                    className="group relative px-8 py-4 bg-brand-gray border border-white/10 rounded-2xl overflow-hidden transition-all hover:border-white/30">
                    <span className="relative z-10 text-white font-black text-xs uppercase tracking-[0.2em] flex items-center gap-3">
                        <Plus className="w-4 h-4" /> Add Exercise
                    </span>
                    <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/5 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000"></div>
                </button>
            </div>

            {/* Add Exercise Modal */}
            {showAddModal && (
                <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-4">
                    <div className="bg-brand-gray/90 border border-white/10 rounded-[40px] w-full max-w-lg overflow-hidden shadow-2xl animate-in zoom-in-95 duration-200">
                        <div className="p-8 border-b border-white/5 flex justify-between items-center">
                            <h2 className="text-2xl font-heading font-black text-white italic uppercase tracking-tighter">Select Exercise</h2>
                            <button onClick={() => setShowAddModal(false)} className="text-gray-500 hover:text-white transition-colors">
                                <X className="w-6 h-6" />
                            </button>
                        </div>
                        <div className="p-4 max-h-[60vh] overflow-y-auto custom-scrollbar">
                            <div className="grid gap-2">
                                {catalog.map((item) => (
                                    <button
                                        key={item.id}
                                        onClick={() => addExerciseToWorkout(item)}
                                        className="w-full p-4 rounded-2xl bg-white/5 border border-white/5 hover:bg-brand-red/10 hover:border-brand-red/30 text-left transition-all group"
                                    >
                                        <div className="flex justify-between items-center">
                                            <div>
                                                <h4 className="font-bold text-white group-hover:text-brand-red transition-colors">{item.name}</h4>
                                                <p className="text-[10px] text-gray-500 uppercase font-black tracking-widest">{item.category} • {item.muscle_group}</p>
                                            </div>
                                            <Plus className="w-4 h-4 text-gray-600 group-hover:text-brand-red" />
                                        </div>
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}


function RestTimer({ onClose }: { onClose: () => void }) {
    const [seconds, setSeconds] = useState(60);

    useEffect(() => {
        if (seconds <= 0) {
            const audio = new Audio("https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3");
            audio.play().catch(() => { });
            onClose();
            return;
        };
        const timer = setInterval(() => setSeconds(s => s - 1), 1000);
        return () => clearInterval(timer);
    }, [seconds, onClose]);

    return (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-50 animate-bounce-in">
            <div className="bg-brand-red text-white px-8 py-4 rounded-3xl shadow-[0_10px_40px_rgba(220,38,38,0.5)] flex items-center gap-6 border border-white/20 backdrop-blur-xl">
                <div className="relative w-12 h-12 flex items-center justify-center">
                    <svg className="absolute inset-0 w-full h-full -rotate-90">
                        <circle
                            cx="24"
                            cy="24"
                            r="20"
                            stroke="currentColor"
                            strokeWidth="4"
                            fill="transparent"
                            className="opacity-20"
                        />
                        <circle
                            cx="24"
                            cy="24"
                            r="20"
                            stroke="currentColor"
                            strokeWidth="4"
                            fill="transparent"
                            strokeDasharray={126}
                            strokeDashoffset={126 - (126 * seconds) / 60}
                            strokeLinecap="round"
                            className="transition-all duration-1000"
                        />
                    </svg>
                    <span className="text-xl font-black italic">{seconds}</span>
                </div>
                <div>
                    <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-80">Rest active</p>
                    <p className="text-sm font-bold">Prepare for next set</p>
                </div>
                <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                    <X className="w-5 h-5" />
                </button>
            </div>
        </div>
    );
}

'use server'

import { revalidatePath } from 'next/cache'
import { redirect } from 'next/navigation'
import { createClient } from '@/utils/supabase/server'

export async function login(prevState: any, formData: FormData) {
    const supabase = await createClient()

    const email = formData.get('email') as string
    const password = formData.get('password') as string

    const { error } = await supabase.auth.signInWithPassword({
        email,
        password,
    })

    // If error, return it to the state
    if (error) {
        return { error: 'Invalid credentials. Please check your email and password.' }
    }

    // If success, redirect (this throws an error in Next.js to handle redirect, so it must be outside try/catch or just straight up)
    revalidatePath('/', 'layout')
    redirect('/dashboard')
}

export async function signup(prevState: any, formData: FormData) {
    const supabase = await createClient()

    const email = formData.get('email') as string
    const password = formData.get('password') as string
    const firstName = formData.get('firstName') as string
    const lastName = formData.get('lastName') as string
    const username = formData.get('username') as string

    const { error } = await supabase.auth.signUp({
        email,
        password,
        options: {
            data: {
                full_name: `${firstName} ${lastName}`,
                username: username,
                avatar_url: `https://ui-avatars.com/api/?name=${firstName}+${lastName}&background=random`
            }
        }
    })

    if (error) {
        console.error("Signup Error Detail:", error);
        return { error: error.message + (error.stack ? ` (Stack: ${error.stack})` : '') }
    }

    revalidatePath('/', 'layout')
    redirect('/dashboard/profile')
}

import { createServerClient } from '@supabase/ssr'
import { NextResponse, type NextRequest } from 'next/server'

export async function updateSession(request: NextRequest) {
    let supabaseResponse = NextResponse.next({
        request,
    })

    // Create client
    const supabase = createServerClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL!,
        process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
        {
            cookies: {
                getAll() {
                    return request.cookies.getAll()
                },
                setAll(cookiesToSet) {
                    cookiesToSet.forEach(({ name, value, options }) =>
                        request.cookies.set(name, value)
                    )

                    supabaseResponse = NextResponse.next({
                        request,
                    })

                    cookiesToSet.forEach(({ name, value, options }) =>
                        supabaseResponse.cookies.set(name, value, options)
                    )
                },
            },
        }
    )

    // Refresh session if needed
    const {
        data: { user },
    } = await supabase.auth.getUser()

    if (request.nextUrl.pathname.startsWith('/dashboard') && !user) {
        const url = request.nextUrl.clone()
        url.pathname = '/login'
        return NextResponse.redirect(url)
    }

    return supabaseResponse
}
